document.addEventListener('DOMContentLoaded', () => {
  initData();
  initInsuranceWorkflows();
  initFontSize();
  initThemeAndMasking();
  initAdminSession();
  setupInputFormatters();
  setupGlobalDatePickerTriggers();

  // Convex Cloud 운영 서버 실시간 데이터 동기화
  if (typeof loadConvexData === 'function') {
    loadConvexData();
  }

  const addrQueryInput = document.getElementById('addressSearchQuery');
  if (addrQueryInput && typeof addrQueryInput.addEventListener === 'function') {
    addrQueryInput.addEventListener('keydown', function(e) {
      if (e.key === 'Enter') {
        e.preventDefault();
        performAddressSearch();
      }
    });
  }

  // 통합허브 검색어 초기화 (브라우저 자동완성/캐시 잔여 방지)
  const clearHubInputSafely = () => {
    const hubInput = document.getElementById('hubSearchInput');
    if (hubInput) {
      hubInput.value = '';
      const clearBtn = document.getElementById('btnHubSearchClear');
      if (clearBtn) clearBtn.classList.add('hidden');
    }
  };
  clearHubInputSafely();
  setTimeout(clearHubInputSafely, 100);
  setTimeout(clearHubInputSafely, 300);
  setTimeout(clearHubInputSafely, 600);
  window.addEventListener('pageshow', clearHubInputSafely);
  window.addEventListener('load', clearHubInputSafely);

  // Render Core Unified Hub immediately for ultra-fast first contentful paint!
  renderUnifiedCareHub();
  initIcons();

  // Lazy render background tabs during idle time to prevent main-thread freeze
  setTimeout(() => {
    renderSamsungList();
    renderAdjusters();
    renderForms();
    renderDashboard();
    renderApplications();
    renderAssignments();
    renderCareLogs();
    renderClaims();
    renderPayouts();
    renderAdmins();
    renderPartners();
    if (typeof renderFaxManagement === 'function') renderFaxManagement();
    if (typeof loadBarobillSettingsToInputs === 'function') loadBarobillSettingsToInputs();
    if (typeof initSamsungCallReportModule === 'function') initSamsungCallReportModule();
    if (typeof initTotalCallAnalysisModule === 'function') initTotalCallAnalysisModule();
    calculateRuleSplit();
  }, 60);

  window.addEventListener('beforeunload', (e) => {
    if (typeof gSamsungPendingChanges !== 'undefined' && gSamsungPendingChanges && gSamsungPendingChanges.size > 0) {
      e.preventDefault();
      e.returnValue = '명단관리에 저장되지 않은 수정사항이 있습니다.';
      return e.returnValue;
    }
  });
});

