function handleSamsungExcelFile(input) {
  const file = input.files[0];
  if (!file) return;

  const reader = new FileReader();
  const isXlsx = file.name.endsWith('.xlsx') || file.name.endsWith('.xls');

  if (isXlsx && typeof XLSX !== 'undefined') {
    reader.onload = function(e) {
      try {
        const data = new Uint8Array(e.target.result);
        const wb = XLSX.read(data, { type: 'array' });
        const firstSheetName = wb.SheetNames[0];
        const ws = wb.Sheets[firstSheetName];
        const jsonRows = XLSX.utils.sheet_to_json(ws, { header: 1 });
        parseSamsungSheetJsonRows(jsonRows);
      } catch (err) {
        console.error('Error parsing xlsx:', err);
        alert('엑셀 파일을 읽는 중 오류가 발생했습니다: ' + err.message);
      }
    };
    reader.readAsArrayBuffer(file);
  } else {
    reader.onload = function(e) {
      const text = e.target.result;
      parseSamsungCsvContent(text);
    };
    reader.readAsText(file);
  }
}

function parseSamsungSheetJsonRows(rows) {
  if (!rows || rows.length === 0) return;
  const records = [];
  let startIdx = 0;
  
  if (rows[0] && (String(rows[0][0]).includes('피보험자') || String(rows[0][0]).includes('ID') || String(rows[0][5]).includes('증권번호'))) {
    startIdx = 1;
  }

  for (let i = startIdx; i < rows.length; i++) {
    const cols = rows[i];
    if (!cols || cols.length < 2) continue;

    records.push({
      id: 'SF-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + String(i).padStart(2, '0'),
      patientId: String(cols[0] || ('SF-P' + (100 + i))).trim(),
      patientName: String(cols[1] || ('고객' + i)).trim(),
      birthDate: String(cols[2] || '19700101').trim(),
      gender: String(cols[3] || '남').trim(),
      phone: String(cols[4] || '010-0000-0000').trim(),
      policyNumber: String(cols[5] || ('SF' + Math.floor(100000000 + Math.random() * 900000000))).trim(),
      productCode: String(cols[6] || 'SF-CARE-01').trim(),
      productName: String(cols[7] || '무배당 삼성화재 당신에게 좋은간병보험').trim(),
      contractStartDate: String(cols[8] || '2024-03-01').trim(),
      contractEndDate: String(cols[9] || '2044-03-01').trim(),
      hasInjuryCare: String(cols[10] || '가입').trim(),
      hasDiseaseCare: String(cols[11] || '가입').trim(),
      accidentNumber: '26S' + String(Math.floor(100000 + Math.random() * 900000)),
      adjusterName: i % 2 === 0 ? '김정현' : '이민우',
      adjusterPhone: i % 2 === 0 ? '02-3485-9114' : '02-760-5521',
      adjusterFax: i % 2 === 0 ? '02-3485-9100' : '02-760-5500',
      maxDailyLimit: 144000,
      maxDays: 180,
      receiveDate: new Date().toISOString().slice(0, 10),
      matchStatus: '신청대기(미신청)'
    });
  }

  gSamsungUploadedExcelRecords = records;
  renderSamsungExcelPreview();
}

function parseSamsungPasteText() {
  const text = document.getElementById('samsungPasteText')?.value || '';
  if (!text.trim()) return;
  parseSamsungCsvContent(text);
}

function parseSamsungCsvContent(text) {
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  if (lines.length === 0) return;

  const records = [];
  let startIdx = 0;
  if (lines[0].includes('피보험자') || lines[0].includes('증권번호') || lines[0].includes('ID')) {
    startIdx = 1;
  }

  for (let i = startIdx; i < lines.length; i++) {
    const delimiter = lines[i].includes('\t') ? '\t' : ',';
    const cols = lines[i].split(delimiter).map(c => c.replace(/^["']|["']$/g, '').trim());
    if (cols.length < 2) continue;

    const patientId = cols[0] || ('SF-P' + (100 + i));
    const patientName = cols[1] || '고객' + i;
    const birthDate = cols[2] || '19700101';
    const gender = cols[3] || '남';
    const phone = cols[4] || '010-0000-0000';
    const policyNumber = cols[5] || ('SF' + Math.floor(100000000 + Math.random() * 900000000));
    const productCode = cols[6] || 'SF-CARE-01';
    const productName = cols[7] || '무배당 삼성화재 당신에게 좋은간병보험';
    const contractStartDate = cols[8] || '2024-03-01';
    const contractEndDate = cols[9] || '2044-03-01';
    const hasInjuryCare = cols[10] || '가입';
    const hasDiseaseCare = cols[11] || '가입';

    records.push({
      id: 'SF-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + String(i).padStart(2, '0'),
      patientId,
      patientName,
      birthDate,
      gender,
      phone,
      policyNumber,
      productCode,
      productName,
      contractStartDate,
      contractEndDate,
      hasInjuryCare,
      hasDiseaseCare,
      accidentNumber: '26S' + String(Math.floor(100000 + Math.random() * 900000)),
      adjusterName: i % 2 === 0 ? '김정현' : '이민우',
      adjusterPhone: i % 2 === 0 ? '02-3485-9114' : '02-760-5521',
      adjusterFax: i % 2 === 0 ? '02-3485-9100' : '02-760-5500',
      maxDailyLimit: 144000,
      maxDays: 180,
      receiveDate: new Date().toISOString().slice(0, 10),
      matchStatus: '신청대기(미신청)'
    });
  }

  gSamsungUploadedExcelRecords = records;
  renderSamsungExcelPreview();
}

function renderSamsungExcelPreview() {
  const previewArea = document.getElementById('samsungExcelPreviewArea');
  const countBadge = document.getElementById('samsungExcelCountBadge');
  const listEl = document.getElementById('samsungExcelPreviewList');
  const btn = document.getElementById('btnConfirmSamsungUpload');
  const progressBox = document.getElementById('samsungUploadProgressBox');

  if (!previewArea || !listEl) return;
  if (progressBox) progressBox.classList.add('hidden');

  if (gSamsungUploadedExcelRecords.length === 0) {
    previewArea.classList.add('hidden');
    if (btn) btn.disabled = true;
    return;
  }

  const totalCount = gSamsungUploadedExcelRecords.length;
  previewArea.classList.remove('hidden');
  if (countBadge) countBadge.innerText = totalCount.toLocaleString() + '건 인식됨';
  if (btn) {
    btn.disabled = false;
    btn.innerHTML = `<i data-lucide="check" class="w-3.5 h-3.5"></i> 삼성화재 명단(${totalCount.toLocaleString()}건) 일괄 등록`;
  }

  // 대용량 데이터(수만 건) DOM 과부하 방지: 상위 30건만 고속 렌더링
  const previewSlice = gSamsungUploadedExcelRecords.slice(0, 30);
  let html = '';

  if (totalCount > 30) {
    html += `
      <div class="p-2.5 bg-sky-100 text-sky-900 rounded-xl font-bold flex items-center justify-between text-xs mb-1">
        <span class="flex items-center gap-1.5">
          <i data-lucide="info" class="w-4 h-4 text-sky-600"></i>
          총 <b>${totalCount.toLocaleString()}건</b> 중 상위 30건 미리보기 표시
        </span>
        <span class="text-[11px] text-sky-700 font-normal">등록 시 전체 ${totalCount.toLocaleString()}건이 고속 분할 업로드됩니다</span>
      </div>
    `;
  }

  html += previewSlice.map(r => `
    <div class="p-2.5 bg-white rounded-xl border border-slate-200 flex items-center justify-between text-[11px] shadow-2xs">
      <div>
        <b class="text-sky-900 font-mono">${r.patientId}</b> · <b class="text-slate-900">${r.patientName}</b> (${r.gender}/${r.birthDate}) · ${r.phone}
        <div class="text-[10px] text-slate-500 font-mono mt-0.5">증권: ${r.policyNumber} | 상품: ${r.productName} (${r.contractStartDate}~${r.contractEndDate}) | 상해: ${r.hasInjuryCare} / 질병: ${r.hasDiseaseCare}</div>
      </div>
      <span class="px-2 py-0.5 bg-sky-100 text-sky-800 rounded-full font-bold text-[10px]">12개항목 검증완료</span>
    </div>
  `).join('');

  if (totalCount > 30) {
    html += `
      <div class="p-2 text-center text-slate-400 text-[11px] font-medium">
        ...외 ${(totalCount - 30).toLocaleString()}건 대기 중
      </div>
    `;
  }

  listEl.innerHTML = html;
  initIcons(listEl);
}

async function confirmSamsungExcelUpload() {
  if (gSamsungUploadedExcelRecords.length === 0) return;

  const total = gSamsungUploadedExcelRecords.length;
  const progressBox = document.getElementById('samsungUploadProgressBox');
  const progressBar = document.getElementById('samsungUploadProgressBar');
  const percentBadge = document.getElementById('samsungUploadPercentBadge');
  const countDetail = document.getElementById('samsungUploadCountDetail');
  const btnConfirm = document.getElementById('btnConfirmSamsungUpload');

  if (progressBox) progressBox.classList.remove('hidden');
  if (btnConfirm) btnConfirm.disabled = true;

  // 1. 메모리 및 IndexedDB에 즉시 병합 저장 (O(1) Map 중복제거)
  const existingMap = new Map((gSamsungList || []).map(r => [r.patientId || r.id, r]));
  for (const r of gSamsungUploadedExcelRecords) {
    const key = r.patientId || r.id;
    if (key) existingMap.set(key, r);
  }
  gSamsungList = Array.from(existingMap.values());

  // IndexedDB에 대용량 안전 영구 저장
  await LivonDB.saveSamsungEligible(gSamsungList);

  // 로컬스토리지는 용량 초과(5MB) 방지를 위해 메타데이터만 안전 보존
  try {
    localStorage.setItem('LIVON_SAMSUNG_COUNT', String(gSamsungList.length));
    if (gSamsungList.length <= 100) {
      localStorage.setItem('LIVON_SAMSUNG_ELIGIBLE', JSON.stringify(gSamsungList));
    } else {
      localStorage.removeItem('LIVON_SAMSUNG_ELIGIBLE');
    }
  } catch (e) {}

  // 2. Convex Cloud 청크 단위 분할 업로드 (200건씩 안전 전송)
  const CHUNK_SIZE = 200;
  let uploaded = 0;

  if (typeof syncToConvex === 'function') {
    for (let i = 0; i < total; i += CHUNK_SIZE) {
      const chunk = gSamsungUploadedExcelRecords.slice(i, i + CHUNK_SIZE);
      try {
        await syncToConvex('sync:saveSamsungEligibleChunk', { leads: chunk });
      } catch (err) {
        console.warn(`[Convex Cloud] 청크 업로드 실패 (${i} ~ ${i + chunk.length}):`, err);
      }

      uploaded = Math.min(uploaded + chunk.length, total);
      const pct = Math.min(100, Math.round((uploaded / total) * 100));

      if (progressBar) progressBar.style.width = pct + '%';
      if (percentBadge) percentBadge.innerText = pct + '%';
      if (countDetail) countDetail.innerText = `${uploaded.toLocaleString()} / ${total.toLocaleString()}건 완료`;

      // 브라우저 렌더링 갱신을 위한 짧은 양보
      await new Promise(r => setTimeout(r, 15));
    }
  }

  // 3. 완료 후 UI 갱신
  if (btnConfirm) btnConfirm.disabled = false;
  closeModal('samsungExcelModal');

  // 스프레드시트 갱신
  gSamsungSheets.eligible = gSamsungList;
  gSamsungSheetPage = 1;
  syncSamsungSpreadsheetData(true);
  switchSamsungSheet('eligible');

  if (typeof showCustomAlert === 'function') {
    showCustomAlert({
      title: '삼성화재 사전명단 대량 등록 완료',
      message: `삼성화재 12대 핵심 항목을 포함한 ${total.toLocaleString()}건의 대상자 명단이 클라우드 DB 및 브라우저 로컬 저장소(IndexedDB)에 영구 보존되었습니다.\n(총 누적 사전명단: ${gSamsungList.length.toLocaleString()}건)\n페이지를 새로고침하거나 창을 닫아도 안전하게 보존됩니다.`,
      icon: 'file-check-2',
      iconColor: 'sky'
    });
  }
}

// =========================================================================
// INTEGRATED DIRECTORY (간병인인력 / 간병센터 / 손사디렉토리) CONTROLLER
// =========================================================================
var gActiveDirectorySubTab = 'caregivers'; // 'caregivers' | 'centers' | 'adjusters'

function switchDirectorySubTab(subTab) {
  if (!subTab) subTab = 'caregivers';
  gActiveDirectorySubTab = subTab;

  const subTabs = ['caregivers', 'centers', 'adjusters'];
  subTabs.forEach(tab => {
    const pane = document.getElementById(`dirSubTab-${tab}`);
    const btn = document.getElementById(`btnDirSubTab-${tab}`);
    if (pane) {
      if (tab === subTab) {
        pane.classList.remove('hidden');
      } else {
        pane.classList.add('hidden');
      }
    }
    if (btn) {
      const badge = btn.querySelector('.dir-badge');
      if (tab === subTab) {
        btn.className = 'dir-subtab-btn px-4 py-2 rounded-xl text-xs font-black bg-emerald-600 text-white shadow-xs flex items-center gap-2 border border-emerald-500 transition-all cursor-pointer whitespace-nowrap';
        if (badge) {
          badge.className = 'dir-badge px-2 py-0.5 rounded-full bg-white text-emerald-950 font-black text-[10.5px] shadow-2xs';
        }
      } else {
        btn.className = 'dir-subtab-btn px-4 py-2 rounded-xl text-xs font-bold bg-slate-100 hover:bg-slate-200 text-slate-700 flex items-center gap-2 border border-slate-200 transition-all cursor-pointer whitespace-nowrap';
        if (badge) {
          badge.className = 'dir-badge px-2 py-0.5 rounded-full bg-slate-200 text-slate-800 font-bold border border-slate-300/60 text-[10.5px]';
        }
      }
    }
  });

  if (subTab === 'caregivers') renderCaregivers();
  else if (subTab === 'centers') renderCenters();
  else if (subTab === 'adjusters') renderAdjusters();

  updateDirectoryTotalBadge();
  initIcons();
}

function updateDirectoryTotalBadge() {
  const cgLen = (gCaregivers || []).length;
  const ctrLen = (gCenters || []).length;
  const adjLen = (gAdjusters || []).length;
  const total = cgLen + ctrLen + adjLen;

  const dirCgBadge = document.getElementById('dirCaregiverCountBadge');
  if (dirCgBadge) dirCgBadge.innerText = `${cgLen}명`;

  const dirCtrBadge = document.getElementById('dirCenterCountBadge');
  if (dirCtrBadge) dirCtrBadge.innerText = `${ctrLen}개소`;

  const dirAdjBadge = document.getElementById('dirAdjusterCountBadge');
  if (dirAdjBadge) dirAdjBadge.innerText = `${adjLen}명`;

  const sidebarCountEl = document.getElementById('sidebarDirectoryCount');
  if (sidebarCountEl) sidebarCountEl.innerText = total;

  const dirHeaderTotalEl = document.getElementById('dirHeaderTotalCount');
  if (dirHeaderTotalEl) dirHeaderTotalEl.innerText = `${total}명/개소`;
}

// -------------------------------------------------------------------------
// DIRECTORY AUTO-SYNC ENGINE (통합허브 입력 시 디렉토리 자동반영 & 동기화)
// -------------------------------------------------------------------------

/**
 * 디렉토리 캐시 저장 (로컬스토리지)
 */
function saveDirectoryToStorage() {
  try {
    if (Array.isArray(gCaregivers)) localStorage.setItem('LIVON_CACHED_CAREGIVERS', JSON.stringify(gCaregivers));
    if (Array.isArray(gCenters)) localStorage.setItem('LIVON_CACHED_CENTERS', JSON.stringify(gCenters));
    if (Array.isArray(gAdjusters)) localStorage.setItem('LIVON_CACHED_ADJUSTERS', JSON.stringify(gAdjusters));
  } catch (e) {
    console.warn('Failed to save directory cache:', e);
  }
}

/**
 * 통합허브 및 고객 정보 입력/수정 과정에서 간병인 신규/수정 시 디렉토리에 자동 반영
 * @param {Object} info 간병인 정보
 * @param {boolean} silent 알림/로그 생략 여부
 */
function autoSyncCaregiverToDirectory(info, silent = false) {
  if (!info || !info.name) return null;
  const name = info.name.trim();
  if (!name || name === '-' || name === '미배정' || name.includes('미배정')) return null;

  if (!Array.isArray(gCaregivers)) gCaregivers = [];

  let cg = gCaregivers.find(c => c && c.name && c.name.trim() === name);
  let isNew = false;

  if (!cg) {
    isNew = true;
    let maxNum = 0;
    gCaregivers.forEach(c => {
      if (c && c.id) {
        const n = parseInt(c.id.replace(/[^0-9]/g, ''), 10);
        if (!isNaN(n) && n > maxNum) maxNum = n;
      }
    });
    const newId = 'CG' + String(Math.max(maxNum + 1, gCaregivers.length + 1)).padStart(3, '0');

    cg = {
      id: newId,
      name: name,
      phone: info.phone || '010-0000-0000',
      centerName: info.centerName || '개인',
      area: info.area || '전국',
      cert: info.cert || '간병사 1급',
      account: info.account || info.accountInfo || '',
      dailyWage: Number(info.dailyWage) || 140000,
      settlementType: info.settlementType || (info.centerName && info.centerName !== '개인' ? '센터' : '개인'),
      birthDate: info.birthDate || '',
      activeCases: 1,
      status: '활동중',
      source: '통합허브 자동연동'
    };
    gCaregivers.push(cg);
  } else {
    // 기존 간병인 정보 최신화
    if (info.phone && (!cg.phone || cg.phone === '010-0000-0000')) cg.phone = info.phone;
    if (info.centerName && (!cg.centerName || cg.centerName === '개인')) cg.centerName = info.centerName;
    if (info.account || info.accountInfo) cg.account = info.account || info.accountInfo;
    if (info.dailyWage) cg.dailyWage = Number(info.dailyWage);
    if (info.settlementType) cg.settlementType = info.settlementType;
    if (info.area && (!cg.area || cg.area === '전국')) cg.area = info.area;
    if (info.birthDate && !cg.birthDate) cg.birthDate = info.birthDate;
    if (cg.status !== '활동중') cg.status = '활동중';
  }

  // 소속 센터명도 협력센터 디렉토리에 자동 반영
  if (cg.centerName && cg.centerName !== '개인' && cg.centerName !== '-') {
    autoSyncCenterToDirectory({
      name: cg.centerName,
      settlementType: cg.settlementType || '센터'
    }, true);
  }

  if (!silent) {
    saveDirectoryToStorage();
    updateDirectoryTotalBadge();
    populateCaregiverDatalist();

    if (typeof renderCaregivers === 'function' && document.getElementById('caregiverTableBody')) {
      renderCaregivers();
    }

    if (isNew) {
      console.log(`[디렉토리 자동연동] 신규 간병인 [${cg.name}] 등록 완료 (ID: ${cg.id}, 소속: ${cg.centerName})`);
    }
  }

  return cg;
}

/**
 * 통합허브 및 고객 정보 입력/수정 과정에서 협력센터 신규/수정 시 디렉토리에 자동 반영
 * @param {Object} info 센터 정보
 * @param {boolean} silent 알림/로그 생략 여부
 */
function autoSyncCenterToDirectory(info, silent = false) {
  if (!info || !info.name) return null;
  const name = info.name.trim();
  if (!name || name === '-' || name === '개인') return null;

  if (!Array.isArray(gCenters)) gCenters = [];

  let ctr = gCenters.find(c => c && c.name && c.name.trim() === name);
  let isNew = false;

  if (!ctr) {
    isNew = true;
    let maxNum = 0;
    gCenters.forEach(c => {
      if (c && c.id) {
        const n = parseInt(c.id.replace(/[^0-9]/g, ''), 10);
        if (!isNaN(n) && n > maxNum) maxNum = n;
      }
    });
    const newId = 'CTR' + String(Math.max(maxNum + 1, gCenters.length + 1)).padStart(3, '0');

    ctr = {
      id: newId,
      name: name,
      manager: info.manager || `${name} 담당`,
      phone: info.phone || '',
      fax: info.fax || '',
      area: info.area || '전국',
      settlementType: info.settlementType || '센터',
      businessNumber: info.businessNumber || '',
      caregiverCount: 1,
      source: '통합허브 자동연동'
    };
    gCenters.push(ctr);
  } else {
    // 기존 센터 정보 최신화
    if (info.manager && (!ctr.manager || ctr.manager.includes('담당'))) ctr.manager = info.manager;
    if (info.phone && !ctr.phone) ctr.phone = info.phone;
    if (info.fax && !ctr.fax) ctr.fax = info.fax;
    if (info.area && (!ctr.area || ctr.area === '전국')) ctr.area = info.area;
    if (info.settlementType) ctr.settlementType = info.settlementType;
    if (info.businessNumber && !ctr.businessNumber) ctr.businessNumber = info.businessNumber;
  }

  // 소속 간병인 수 자동 계산
  if (Array.isArray(gCaregivers)) {
    const count = gCaregivers.filter(c => c && c.centerName === name).length;
    if (count > 0) ctr.caregiverCount = count;
  }

  if (!silent) {
    saveDirectoryToStorage();
    updateDirectoryTotalBadge();
    populateCenterDatalist();

    if (typeof renderCenters === 'function' && document.getElementById('centerTableBody')) {
      renderCenters();
    }

    // Convex Cloud 실시간 연동 (단일 수동 등록/수정 시에만 발송)
    if (typeof syncToConvex === 'function') {
      syncToConvex('sync:savePartner', { partner: ctr }).catch(() => {});
    }

    if (isNew) {
      console.log(`[디렉토리 자동연동] 신규 간병센터 [${ctr.name}] 등록 완료 (ID: ${ctr.id})`);
    }
  }

  return ctr;
}

/**
 * 통합허브 및 고객 정보 입력/수정 과정에서 손해사정인 신규/수정 시 디렉토리에 자동 반영
 * @param {Object} info 손사 정보
 * @param {boolean} silent 알림/로그 생략 여부
 */
function autoSyncAdjusterToDirectory(info, silent = false) {
  if (!info || !info.name) return null;
  const name = info.name.trim();
  if (!name || name === '-' || name === '미지정' || name.includes('미지정')) return null;

  if (!Array.isArray(gAdjusters)) gAdjusters = [];

  const insCompany = info.insuranceCompany || '현대해상';
  let adj = gAdjusters.find(a => a && a.name && a.name.trim() === name);
  let isNew = false;

  const defaultFirm = (insCompany.includes('삼성')) 
    ? '삼성화재애니카손해사정' 
    : (insCompany.includes('현대') ? '하이라이프손해사정' : '손해사정법인');

  if (!adj) {
    isNew = true;
    let maxNum = 0;
    gAdjusters.forEach(a => {
      if (a && a.id) {
        const n = parseInt(a.id.replace(/[^0-9]/g, ''), 10);
        if (!isNaN(n) && n > maxNum) maxNum = n;
      }
    });
    const newId = 'ADJ' + String(Math.max(maxNum + 1, gAdjusters.length + 1)).padStart(3, '0');

    adj = {
      id: newId,
      insuranceCompany: insCompany,
      firm: info.firm || info.adjusterFirm || defaultFirm,
      branch: info.branch || '보상센터',
      name: name,
      phone: info.phone || info.adjusterPhone || '',
      mobile: info.mobile || info.adjusterMobile || info.phone || '',
      fax: info.fax || info.adjusterFax || '',
      email: info.email || '',
      activeCases: 1,
      status: '정상',
      source: '통합허브 자동연동'
    };
    gAdjusters.push(adj);
  } else {
    // 기존 손사 정보 최신화
    if (info.insuranceCompany && (!adj.insuranceCompany || adj.insuranceCompany === '현대해상')) adj.insuranceCompany = info.insuranceCompany;
    if ((info.firm || info.adjusterFirm) && (!adj.firm || adj.firm === '하이라이프손해사정')) adj.firm = info.firm || info.adjusterFirm;
    if (info.branch && (!adj.branch || adj.branch === '관할팀')) adj.branch = info.branch;
    if ((info.phone || info.adjusterPhone) && !adj.phone) adj.phone = info.phone || info.adjusterPhone;
    if ((info.mobile || info.adjusterMobile) && !adj.mobile) adj.mobile = info.mobile || info.adjusterMobile;
    if ((info.fax || info.adjusterFax) && (!adj.fax || adj.fax === '051-602-5700')) adj.fax = info.fax || info.adjusterFax;
    if (info.email && !adj.email) adj.email = info.email;
  }

  if (!silent) {
    saveDirectoryToStorage();
    updateDirectoryTotalBadge();
    populateAdjusterDatalist();

    if (typeof renderAdjusters === 'function' && document.getElementById('adjusterTableBody')) {
      renderAdjusters();
    }

    // Convex Cloud 실시간 연동 (단일 신규 등록/수정 시에만 발송)
    if (typeof syncToConvex === 'function') {
      syncToConvex('sync:saveAdjuster', { adjuster: adj }).catch(() => {});
    }

    if (isNew) {
      console.log(`[디렉토리 자동연동] 신규 손해사정인 [${adj.name}] 등록 완료 (ID: ${adj.id}, 소속: ${adj.firm})`);
    }
  }

  return adj;
}

/**
 * 손사 자동완성 datalist 채우기
 */
function populateAdjusterDatalist() {
  const datalist = document.getElementById('allAdjustersDataList');
  if (!datalist || !Array.isArray(gAdjusters)) return;
  datalist.innerHTML = gAdjusters.map(a => `
    <option value="${a.name}">${a.name} (${a.insuranceCompany || '보험사'} · ${a.firm || ''} · ${a.phone || ''} · FAX: ${a.fax || ''})</option>
  `).join('');
}

/**
 * 센터 자동완성 datalist 채우기
 */
function populateCenterDatalist() {
  const datalist = document.getElementById('allCentersDataList');
  if (!datalist || !Array.isArray(gCenters)) return;
  datalist.innerHTML = gCenters.map(c => `
    <option value="${c.name}">${c.name} (${c.area || '전국'} · ${c.phone || ''} · ${c.settlementType || '센터'})</option>
  `).join('');

  const cgCenterDatalist = document.getElementById('cgCenterDataList');
  if (cgCenterDatalist) {
    cgCenterDatalist.innerHTML = gCenters.map(c => `<option value="${c.name}">`).join('');
  }
}

/**
 * 손사 성명 입력 시 기존 등록된 손사 연락처 자동완성 보조
 */
function onAdjusterNameInput(val, context = 'custEdit') {
  if (!val || !Array.isArray(gAdjusters)) return;
  const trimmed = val.trim();
  const match = gAdjusters.find(a => a && a.name && (a.name === trimmed || a.name.toLowerCase() === trimmed.toLowerCase()));
  if (!match) return;

  if (context === 'custEdit') {
    const phoneEl = document.getElementById('custEditAdjusterPhone');
    const mobileEl = document.getElementById('custEditAdjusterMobile');
    const faxEl = document.getElementById('custEditAdjusterFax');
    if (phoneEl && match.phone && !phoneEl.value) phoneEl.value = match.phone;
    if (mobileEl && match.mobile && !mobileEl.value) mobileEl.value = match.mobile;
    if (faxEl && match.fax && !faxEl.value) faxEl.value = match.fax;
  } else if (context === 'adjEdit') {
    const firmEl = document.getElementById('adjEditFirm');
    const phoneEl = document.getElementById('adjEditPhone');
    const mobileEl = document.getElementById('adjEditMobile');
    const faxEl = document.getElementById('adjEditFax');
    const insEl = document.getElementById('adjEditInsuranceCompany');
    if (firmEl && match.firm && !firmEl.value) firmEl.value = match.firm;
    if (phoneEl && match.phone && !phoneEl.value) phoneEl.value = match.phone;
    if (mobileEl && match.mobile && !mobileEl.value) mobileEl.value = match.mobile;
    if (faxEl && match.fax && !faxEl.value) faxEl.value = match.fax;
    if (insEl && match.insuranceCompany) insEl.value = match.insuranceCompany;
  } else if (context === 'newAppSamsung') {
    const phoneEl = document.getElementById('newAppSamsungAdjusterPhone');
    const faxEl = document.getElementById('newAppSamsungAdjusterFax');
    if (phoneEl && match.phone) phoneEl.value = match.phone;
    if (faxEl && match.fax) faxEl.value = match.fax;
  }
}

/**
 * 센터명 입력 시 기존 등록된 센터 정산유형 및 연락처 자동완성 보조
 */
function onCenterNameInput(val, context = 'newAssign') {
  if (!val || !Array.isArray(gCenters)) return;
  const trimmed = val.trim();
  const match = gCenters.find(c => c && c.name && (c.name === trimmed || c.name.toLowerCase() === trimmed.toLowerCase()));
  if (!match) return;

  if (context === 'newAssign') {
    const typeSelect = document.getElementById('newAssignSettlementType');
    if (typeSelect && match.settlementType) typeSelect.value = match.settlementType;
  } else if (context === 'schedEdit') {
    const phoneEl = document.getElementById('schedEditCenterPhone');
    const typeSelect = document.getElementById('schedEditSettlementType');
    if (phoneEl && match.phone && !phoneEl.value) phoneEl.value = match.phone;
    if (typeSelect && match.settlementType) typeSelect.value = match.settlementType;
  }
}

let gDirectoriesInitialSynced = false;

/**
 * 시스템 초기화 시 기존 고객 신청 및 배정 데이터로부터
 * 손해사정인, 간병인, 간병센터를 고속(O(1) Set 기반)으로 추출하여 디렉토리에 자동 등록
 * - 1회 실행 후 중복 실행 차단 (force=true 로 강제 가능)
 * - 수만 건 리스트 전수 순회로 인한 브라우저 프리징 완전 해결
 */
function syncDirectoriesFromAllExistingRecords(force = false) {
  if (gDirectoriesInitialSynced && !force) return;
  gDirectoriesInitialSynced = true;

  if (!Array.isArray(gCaregivers)) gCaregivers = [];
  if (!Array.isArray(gCenters)) gCenters = [];
  if (!Array.isArray(gAdjusters)) gAdjusters = [];

  let hasNew = false;
  const existingAdj = new Set(gAdjusters.map(a => (a && a.name ? a.name.trim().toLowerCase() : '')).filter(Boolean));
  const existingCg = new Set(gCaregivers.map(c => (c && c.name ? c.name.trim().toLowerCase() : '')).filter(Boolean));
  const existingCtr = new Set(gCenters.map(c => (c && c.name ? c.name.trim().toLowerCase() : '')).filter(Boolean));

  // 1. 고객 신청 대장(gApps)에서 손해사정인 추출
  if (Array.isArray(gApps)) {
    for (let i = 0; i < gApps.length; i++) {
      const app = gApps[i];
      if (!app || !app.adjusterName) continue;
      const key = app.adjusterName.trim().toLowerCase();
      if (!existingAdj.has(key)) {
        existingAdj.add(key);
        hasNew = true;
        autoSyncAdjusterToDirectory({
          name: app.adjusterName,
          insuranceCompany: app.insuranceCompany,
          firm: app.adjusterFirm,
          phone: app.adjusterPhone,
          mobile: app.adjusterMobile,
          fax: app.adjusterFax
        }, true);
      }
    }
  }

  // 2. 배정 대장(gAssigns)에서 간병인 및 협력센터 추출
  if (Array.isArray(gAssigns)) {
    for (let i = 0; i < gAssigns.length; i++) {
      const as = gAssigns[i];
      if (!as) continue;
      if (as.caregiverName) {
        const cgKey = as.caregiverName.trim().toLowerCase();
        if (!existingCg.has(cgKey)) {
          existingCg.add(cgKey);
          hasNew = true;
          autoSyncCaregiverToDirectory({
            name: as.caregiverName,
            phone: as.phone || as.caregiverPhone,
            centerName: as.centerName,
            account: as.accountInfo,
            dailyWage: as.dailyWage,
            settlementType: as.settlementType
          }, true);
        }
      }
      if (as.centerName) {
        const ctrKey = as.centerName.trim().toLowerCase();
        if (!existingCtr.has(ctrKey)) {
          existingCtr.add(ctrKey);
          hasNew = true;
          autoSyncCenterToDirectory({
            name: as.centerName,
            phone: as.centerPhone,
            settlementType: as.settlementType
          }, true);
        }
      }
    }
  }

  // 3. 삼성화재 주소록에서 담당 손사 추출
  if (Array.isArray(gSamsungAddressBook)) {
    for (let i = 0; i < gSamsungAddressBook.length; i++) {
      const contact = gSamsungAddressBook[i];
      if (!contact || !contact.name) continue;
      const key = contact.name.trim().toLowerCase();
      if (!existingAdj.has(key)) {
        existingAdj.add(key);
        hasNew = true;
        autoSyncAdjusterToDirectory({
          name: contact.name,
          insuranceCompany: '삼성화재',
          firm: contact.team || '삼성화재 보상지원파트',
          phone: contact.phone,
          email: contact.email
        }, true);
      }
    }
  }

  // 4. 삼성 사전명단(gSamsungList): 대용량 데이터이므로 최대 최근 300건만 안전하게 스캔
  if (Array.isArray(gSamsungList) && gSamsungList.length > 0) {
    const scanLimit = Math.min(gSamsungList.length, 300);
    const startIdx = Math.max(0, gSamsungList.length - scanLimit);
    for (let i = startIdx; i < gSamsungList.length; i++) {
      const lead = gSamsungList[i];
      if (!lead || !lead.adjusterName) continue;
      const key = lead.adjusterName.trim().toLowerCase();
      if (!existingAdj.has(key)) {
        existingAdj.add(key);
        hasNew = true;
        autoSyncAdjusterToDirectory({
          name: lead.adjusterName,
          insuranceCompany: '삼성화재',
          firm: '삼성화재애니카손해사정',
          phone: lead.adjusterPhone,
          fax: lead.adjusterFax
        }, true);
      }
    }
  }

  if (hasNew) {
    saveDirectoryToStorage();
  }
  updateDirectoryTotalBadge();
  populateAdjusterDatalist();
  populateCenterDatalist();
  populateCaregiverDatalist();
}

// -------------------------------------------------------------------------
// 2. ADJUSTER DIRECTORY TAB
// -------------------------------------------------------------------------
function renderAdjusters() {
  const tbody = document.getElementById('adjusterTableBody');
  if (!tbody) return;

  const query = (document.getElementById('adjusterSearchInput')?.value || '').trim().toLowerCase();
  const insFilter = document.getElementById('adjusterInsFilter')?.value || 'ALL';

  const filtered = gAdjusters.filter(adj => {
    if (insFilter !== 'ALL' && !adj.insuranceCompany.includes(insFilter)) return false;
    if (!query) return true;
    return (adj.name && adj.name.toLowerCase().includes(query)) ||
           (adj.firm && adj.firm.toLowerCase().includes(query)) ||
           (adj.branch && adj.branch.toLowerCase().includes(query)) ||
           (adj.fax && adj.fax.includes(query));
  });

  const countEl = document.getElementById('adjusterListCount');
  if (countEl) countEl.innerText = filtered.length;
  updateDirectoryTotalBadge();

  tbody.innerHTML = filtered.map(adj => {
    const isChecked = gLedgerSelection.adjusters && gLedgerSelection.adjusters.has(adj.id);
    return `
    <tr class="hover:bg-slate-50 transition-colors ${isChecked ? 'bg-emerald-50/30' : ''}">
      <td class="p-3 pl-4 w-8 text-center">
        <input type="checkbox" value="${adj.id}" ${isChecked ? 'checked' : ''} onchange="toggleSelectRow('adjusters', '${adj.id}', this.checked)" class="adjusters-row-checkbox w-4 h-4 rounded text-emerald-600 focus:ring-emerald-500 cursor-pointer accent-emerald-600">
      </td>
      <td class="p-3 font-mono font-bold text-emerald-800">${adj.id}</td>
      <td class="p-3 font-semibold text-slate-800">${adj.insuranceCompany}</td>
      <td class="p-3 text-slate-700">${adj.firm}</td>
      <td class="p-3 text-slate-600">${adj.branch}</td>
      <td class="p-3 font-black text-slate-900 text-sm">
        ${maskName(adj.name)}
        ${adj.source === '통합허브 자동연동' ? '<span class="ml-1.5 px-1.5 py-0.5 rounded text-[10px] font-black bg-purple-50 text-purple-700 border border-purple-200">허브연동</span>' : ''}
      </td>
      <td class="p-3 font-mono text-slate-700">${adj.phone}</td>
      <td class="p-3 font-mono text-slate-500">${maskPhone(adj.mobile)}</td>
      <td class="p-3 font-mono font-black text-purple-900 bg-purple-50/50">${adj.fax}</td>
      <td class="p-3 font-mono text-slate-500">${adj.email}</td>
      <td class="p-3 text-center font-bold text-emerald-700">${adj.activeCases}건</td>
      <td class="p-3 text-center pr-4">
        <div class="flex items-center justify-center gap-1.5">
          <button onclick="openAdjusterModal('${adj.id}')" class="p-1 rounded hover:bg-slate-200 text-slate-600 font-bold text-[11px]">수정</button>
          <button onclick="deleteAdjuster('${adj.id}')" class="p-1 rounded hover:bg-rose-100 text-rose-600 text-[11px]">삭제</button>
        </div>
      </td>
    </tr>
    `;
  }).join('');
}

function openAdjusterModal(adjId = null) {
  const form = document.querySelector('#adjusterModal form');
  if (form) form.reset();

  if (adjId) {
    const adj = gAdjusters.find(a => a.id === adjId);
    if (adj) {
      document.getElementById('adjEditId').value = adj.id;
      document.getElementById('adjInsurance').value = adj.insuranceCompany;
      document.getElementById('adjName').value = adj.name;
      document.getElementById('adjFirm').value = adj.firm;
      document.getElementById('adjBranch').value = adj.branch;
      document.getElementById('adjPhone').value = adj.phone;
      document.getElementById('adjMobile').value = adj.mobile;
      document.getElementById('adjFax').value = adj.fax;
      document.getElementById('adjEmail').value = adj.email;
    }
  } else {
    document.getElementById('adjEditId').value = '';
  }
  openModal('adjusterModal');
}

function handleAdjusterSubmit(e) {
  e.preventDefault();
  const id = document.getElementById('adjEditId').value || ('ADJ' + String(gAdjusters.length + 1).padStart(3, '0'));
  const newAdj = {
    id: id,
    insuranceCompany: document.getElementById('adjInsurance').value,
    name: document.getElementById('adjName').value.trim(),
    firm: document.getElementById('adjFirm').value.trim(),
    branch: document.getElementById('adjBranch').value.trim(),
    phone: document.getElementById('adjPhone').value.trim(),
    mobile: document.getElementById('adjMobile').value.trim(),
    fax: document.getElementById('adjFax').value.trim(),
    email: document.getElementById('adjEmail').value.trim(),
    activeCases: 0,
    status: '정상'
  };

  const existIdx = gAdjusters.findIndex(a => a.id === id);
  if (existIdx !== -1) {
    gAdjusters[existIdx] = { ...gAdjusters[existIdx], ...newAdj };
  } else {
    gAdjusters.unshift(newAdj);
  }

  saveDirectoryToStorage();
  updateDirectoryTotalBadge();
  populateAdjusterDatalist();

  closeModal('adjusterModal');
  renderAdjusters();
  alert('손해사정인 정보가 성공적으로 저장되었습니다.');
}

function deleteAdjuster(id) {
  if (confirm('이 손해사정인 정보를 삭제하시겠습니까?')) {
    gAdjusters = gAdjusters.filter(a => a.id !== id);
    saveDirectoryToStorage();
    updateDirectoryTotalBadge();
    populateAdjusterDatalist();
    renderAdjusters();
  }
}

// -------------------------------------------------------------------------
// CAREGIVER DIRECTORY TAB (간병인 인력 풀 관리)
// -------------------------------------------------------------------------
function renderCaregivers() {
  const tbody = document.getElementById('caregiverTableBody');
  if (!tbody) return;

  const query = (document.getElementById('caregiverSearchInput')?.value || '').trim().toLowerCase();
  const centerFilter = document.getElementById('caregiverCenterFilter')?.value || 'ALL';
  const statusFilter = document.getElementById('caregiverStatusFilter')?.value || 'ALL';

  // Populate center select filter if not yet populated
  const centerSelect = document.getElementById('caregiverCenterFilter');
  if (centerSelect && centerSelect.options && centerSelect.options.length <= 1) {
    const centers = Array.from(new Set(gCaregivers.map(c => c.centerName).filter(Boolean)));
    centers.forEach(ctr => {
      const opt = document.createElement('option');
      opt.value = ctr;
      opt.text = ctr;
      centerSelect.appendChild(opt);
    });
  }

  const filtered = gCaregivers.filter(cg => {
    if (centerFilter !== 'ALL' && cg.centerName !== centerFilter) return false;
    if (statusFilter !== 'ALL' && cg.status !== statusFilter) return false;
    if (!query) return true;
    return (cg.id && cg.id.toLowerCase().includes(query)) ||
           (cg.name && cg.name.toLowerCase().includes(query)) ||
           (cg.phone && cg.phone.includes(query)) ||
           (cg.centerName && cg.centerName.toLowerCase().includes(query)) ||
           (cg.area && cg.area.toLowerCase().includes(query)) ||
           (cg.cert && cg.cert.toLowerCase().includes(query));
  });

  const countEl = document.getElementById('caregiverListCount');
  if (countEl) countEl.innerText = filtered.length;
  const sidebarCountEl = document.getElementById('sidebarCaregiverCount');
  if (sidebarCountEl) sidebarCountEl.innerText = gCaregivers.length;
  updateDirectoryTotalBadge();

  if (filtered.length === 0) {
    tbody.innerHTML = `<tr><td colspan="11" class="p-8 text-center text-slate-400">조건에 일치하는 간병인이 없습니다.</td></tr>`;
    return;
  }

  tbody.innerHTML = filtered.map(cg => {
    const isChecked = gLedgerSelection.caregivers && gLedgerSelection.caregivers.has(cg.id);
    const statusBg = cg.status === '활동중' ? 'bg-emerald-100 text-emerald-800' : (cg.status === '대기중' ? 'bg-sky-100 text-sky-800' : 'bg-slate-100 text-slate-600');
    return `
      <tr class="hover:bg-slate-50 transition-colors ${isChecked ? 'bg-emerald-50/30' : ''}">
        <td class="p-3 pl-4 w-8 text-center">
          <input type="checkbox" value="${cg.id}" ${isChecked ? 'checked' : ''} onchange="toggleSelectRow('caregivers', '${cg.id}', this.checked)" class="caregivers-row-checkbox w-4 h-4 rounded text-emerald-600 focus:ring-emerald-500 cursor-pointer accent-emerald-600">
        </td>
        <td class="p-3 font-mono font-bold text-emerald-800">${cg.id}</td>
        <td class="p-3 font-bold text-slate-900">
          ${maskName(cg.name)}
          ${cg.source === '통합허브 자동연동' ? '<span class="ml-1.5 px-1.5 py-0.5 rounded text-[10px] font-black bg-emerald-50 text-emerald-700 border border-emerald-200">허브연동</span>' : ''}
        </td>
        <td class="p-3 font-mono text-slate-600">${maskPhone(cg.phone)}</td>
        <td class="p-3 font-semibold text-slate-800">${cg.centerName || '개인'}</td>
        <td class="p-3 text-slate-600">${cg.area || '-'}</td>
        <td class="p-3"><span class="px-2 py-0.5 rounded bg-slate-100 text-slate-700 font-medium">${cg.cert || '간병사'}</span></td>
        <td class="p-3 font-mono text-slate-500">${maskAccount(cg.account)}</td>
        <td class="p-3 text-center font-bold text-primary-700">${cg.activeCases || 0}건</td>
        <td class="p-3 text-center">
          <span class="px-2.5 py-0.5 rounded-full text-[11px] font-bold ${statusBg}">${cg.status || '활동중'}</span>
        </td>
        <td class="p-3 text-center pr-4">
          <div class="flex items-center justify-center gap-1.5">
            <button onclick="openCaregiverModal('${cg.id}')" class="p-1 rounded hover:bg-slate-200 text-slate-600 font-bold text-[11px]" title="수정">수정</button>
            <button onclick="deleteCaregiver('${cg.id}')" class="p-1 rounded hover:bg-rose-100 text-rose-600 font-bold text-[11px]" title="삭제">삭제</button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
  initIcons(tbody);
}

function openCaregiverModal(id = null) {
  const datalist = document.getElementById('cgCenterDataList');
  if (datalist) {
    datalist.innerHTML = gCenters.map(c => `<option value="${c.name}">`).join('');
  }

  if (id) {
    const cg = gCaregivers.find(c => c.id === id);
    if (!cg) return;
    document.getElementById('cgEditId').value = cg.id;
    document.getElementById('caregiverModalTitle').innerText = '간병인 정보 수정 (' + cg.id + ')';
    document.getElementById('cgName').value = cg.name || '';
    document.getElementById('cgPhone').value = cg.phone || '';
    document.getElementById('cgCenter').value = cg.centerName || '';
    document.getElementById('cgArea').value = cg.area || '';
    document.getElementById('cgCert').value = cg.cert || '간병사 1급';
    document.getElementById('cgStatus').value = cg.status || '활동중';
    document.getElementById('cgAccount').value = cg.account || '';
  } else {
    document.getElementById('cgEditId').value = '';
    document.getElementById('caregiverModalTitle').innerText = '신규 간병인 등록';
    document.getElementById('cgName').value = '';
    document.getElementById('cgPhone').value = '';
    document.getElementById('cgCenter').value = '';
    document.getElementById('cgArea').value = '';
    document.getElementById('cgCert').value = '간병사 1급';
    document.getElementById('cgStatus').value = '활동중';
    document.getElementById('cgAccount').value = '';
  }
  openModal('caregiverModal');
  initIcons();
}

function handleCaregiverSubmit(e) {
  e.preventDefault();
  const id = document.getElementById('cgEditId').value;
  const name = document.getElementById('cgName').value.trim();
  const phone = document.getElementById('cgPhone').value.trim();
  const centerName = document.getElementById('cgCenter').value.trim();
  const area = document.getElementById('cgArea').value.trim();
  const cert = document.getElementById('cgCert').value;
  const status = document.getElementById('cgStatus').value;
  const account = document.getElementById('cgAccount').value.trim();

  if (id) {
    const cg = gCaregivers.find(c => c.id === id);
    if (cg) {
      cg.name = name;
      cg.phone = phone;
      cg.centerName = centerName;
      cg.area = area;
      cg.cert = cert;
      cg.status = status;
      cg.account = account;
    }
    alert(`[${name}] 간병인 정보가 성공적으로 수정되었습니다.`);
  } else {
    const newId = 'CG' + (gCaregivers.length + 1).toString().padStart(3, '0');
    gCaregivers.unshift({
      id: newId,
      name,
      phone,
      centerName: centerName || '개인',
      area,
      cert,
      status,
      account,
      activeCases: 0
    });
    alert(`신규 간병인 [${name}] 등록이 완료되었습니다. (ID: ${newId})`);
  }

  saveDirectoryToStorage();
  updateDirectoryTotalBadge();
  populateCaregiverDatalist();

  closeModal('caregiverModal');
  renderCaregivers();
}

function deleteCaregiver(id) {
  const idx = gCaregivers.findIndex(c => c.id === id);
  if (idx < 0) return;
  const cg = gCaregivers[idx];
  if (!confirm(`간병인 [${cg.name}] (${cg.id}) 정보를 인력 풀에서 삭제하시겠습니까?`)) return;
  gCaregivers.splice(idx, 1);
  saveDirectoryToStorage();
  updateDirectoryTotalBadge();
  populateCaregiverDatalist();
  renderCaregivers();
}

function openCaregiverExcelModal() {
  document.getElementById('caregiverExcelPreviewArea').classList.add('hidden');
  document.getElementById('btnConfirmCaregiverUpload').disabled = true;
  openModal('caregiverExcelModal');
  initIcons();
}

