function updateSidebarCounts() {
  const appCountEl = document.getElementById('sidebarAppCount');
  if (appCountEl) appCountEl.innerText = (gApps || []).length;

  const assignCountEl = document.getElementById('sidebarAssignCount');
  if (assignCountEl) assignCountEl.innerText = (gAssigns || []).length;

  const claimCountEl = document.getElementById('sidebarClaimCount');
  if (claimCountEl) claimCountEl.innerText = (gClaims || []).length;

  const payoutCountEl = document.getElementById('sidebarPayoutCount');
  if (payoutCountEl) payoutCountEl.innerText = (gPayouts || []).length;

  const adjCountEl = document.getElementById('sidebarAdjusterCount');
  if (adjCountEl) adjCountEl.innerText = (gAdjusters || []).length;

  const cgCountEl = document.getElementById('sidebarCaregiverCount');
  if (cgCountEl) cgCountEl.innerText = (gCaregivers || []).length;

  const centerCountEl = document.getElementById('sidebarCenterCount');
  if (centerCountEl) centerCountEl.innerText = (gCenters || []).length;

  const faxCountEl = document.getElementById('sidebarFaxCount');
  if (faxCountEl) faxCountEl.innerText = (gFaxLogs || []).length + '건';

  const calCountEl = document.getElementById('sidebarCalendarCount');
  if (calCountEl) {
    const activeCount = (gAssigns || []).filter(a => a && (a.status === '배정완료' || a.status === '진행중')).length || (gAssigns || []).length;
    calCountEl.innerText = activeCount > 0 ? `${activeCount}건` : '스케줄';
  }

  const unpaidBadge = document.getElementById('unpaidAlertBadge');
  if (unpaidBadge) {
    const unpaidCount = (gClaims || []).filter(c => c && (c.depositStatus === '미수' || c.depositStatus === '미확인' || c.depositStatus === '부분입금' || !c.depositStatus)).length;
    unpaidBadge.innerText = unpaidCount;
    unpaidBadge.style.display = unpaidCount > 0 ? 'flex' : 'none';
  }

  updateDirectoryTotalBadge();
}

function initIcons() {
  try {
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
  } catch (e) {
    console.warn('Lucide icon error:', e);
  }
}

function formatPhoneNumber(value) {
  if (!value) return '';
  const clean = value.replace(/[^0-9]/g, '');
  
  if (clean.startsWith('15') || clean.startsWith('16') || clean.startsWith('18')) {
    if (clean.length <= 4) return clean;
    return clean.slice(0, 4) + '-' + clean.slice(4, 8);
  }
  if (clean.startsWith('02')) {
    if (clean.length <= 2) return clean;
    if (clean.length <= 5) return clean.slice(0, 2) + '-' + clean.slice(2);
    if (clean.length <= 9) return clean.slice(0, 2) + '-' + clean.slice(2, 5) + '-' + clean.slice(5);
    return clean.slice(0, 2) + '-' + clean.slice(2, 6) + '-' + clean.slice(6, 10);
  }
  if (clean.length <= 3) return clean;
  if (clean.length <= 6) return clean.slice(0, 3) + '-' + clean.slice(3);
  if (clean.length <= 10) return clean.slice(0, 3) + '-' + clean.slice(3, 6) + '-' + clean.slice(6);
  return clean.slice(0, 3) + '-' + clean.slice(3, 7) + '-' + clean.slice(7, 11);
}

function formatBusinessNumber(value) {
  if (!value) return '';
  const clean = value.replace(/[^0-9]/g, '');
  if (clean.length <= 3) return clean;
  if (clean.length <= 5) return clean.slice(0, 3) + '-' + clean.slice(3);
  return clean.slice(0, 3) + '-' + clean.slice(3, 5) + '-' + clean.slice(5, 10);
}

function formatCurrency(num) {
  if (num === null || num === undefined || isNaN(num)) return '0';
  return Math.round(num).toLocaleString('ko-KR');
}

function maskName(name) {
  if (!name || !gIsMasked) return name || '';
  const match = String(name).match(/^([가-힣a-zA-Z]+)(\s*\(.*?\))?$/);
  if (match) {
    const base = match[1];
    const suffix = match[2] || '';
    let maskedBase = base;
    if (base.length <= 1) maskedBase = base;
    else if (base.length === 2) maskedBase = base[0] + '*';
    else maskedBase = base[0] + '*'.repeat(base.length - 2) + base[base.length - 1];
    return maskedBase + suffix;
  }
  const str = String(name);
  if (str.length <= 1) return str;
  if (str.length === 2) return str[0] + '*';
  return str[0] + '*'.repeat(str.length - 2) + str[str.length - 1];
}

function maskPhone(phone) {
  if (!phone || !gIsMasked) return phone || '';
  const str = String(phone).trim();
  const cleaned = str.replace(/[^0-9]/g, '');
  if (cleaned.length === 11) {
    return cleaned.slice(0, 3) + '-****-' + cleaned.slice(7);
  } else if (cleaned.length === 10) {
    if (cleaned.startsWith('02')) {
      return cleaned.slice(0, 2) + '-****-' + cleaned.slice(6);
    }
    return cleaned.slice(0, 3) + '-***-' + cleaned.slice(6);
  } else if (cleaned.length === 9 && cleaned.startsWith('02')) {
    return cleaned.slice(0, 2) + '-***-' + cleaned.slice(5);
  }
  const parts = str.split('-');
  if (parts.length === 3) {
    return parts[0] + '-****-' + parts[2];
  }
  return str;
}

function maskBirth(birth) {
  if (!birth || !gIsMasked) return birth || '';
  const str = String(birth).trim();
  if (str.length >= 6) {
    return str.slice(0, 4) + '****' + (str.length > 8 ? str.slice(8) : '');
  }
  return str;
}

function maskAccount(acc) {
  if (!acc || !gIsMasked) return acc || '';
  return String(acc).replace(/(\d{3,4})[- ]?(\d{2,4})[- ]?(\d{3,6})/g, '$1-****-****');
}

function maskContactString(contact) {
  if (!contact || !gIsMasked) return contact || '';
  let str = String(contact);
  str = str.replace(/(\d{2,3})[- ]?(\d{3,4})[- ]?(\d{4})/g, (m, p1, p2, p3) => `${p1}-****-${p3}`);
  str = str.replace(/^([가-힣]{2,4})(\s*\(|\s|$)/, (m, name, trail) => {
    return maskName(name) + trail;
  });
  return str;
}

// Global exposure for all modules (total-call-analysis, samsung-call-report, etc.)
if (typeof window !== 'undefined') {
  window.maskName = maskName;
  window.maskPhone = maskPhone;
  window.maskBirth = maskBirth;
  window.maskAccount = maskAccount;
  window.maskContactString = maskContactString;
}

