function calculateAndSetEndDate() {
  const startDateStr = (document.getElementById('newAppDesiredDate')?.value || '').trim();
  const expectedDaysStr = (document.getElementById('newAppExpectedDays')?.value || '').trim();
  const endDateInput = document.getElementById('newAppEndDate');
  const endDatePicker = document.getElementById('newAppEndDate_picker');

  if (!endDateInput) return;

  // 사용기간이 미정이거나 퇴원시까지, 장기예상 등 불특정 기간인 경우 종료예정일 값 비우기
  if (!startDateStr || !expectedDaysStr || expectedDaysStr.includes('미정') || expectedDaysStr.includes('퇴원') || expectedDaysStr.includes('장기')) {
    endDateInput.value = '';
    if (endDatePicker) endDatePicker.value = '';
    return;
  }

  let days = 0;
  if (expectedDaysStr.includes('주')) {
    const m = expectedDaysStr.match(/(\d+)\s*주/);
    if (m) days = parseInt(m[1], 10) * 7;
  } else if (expectedDaysStr.includes('개월') || expectedDaysStr.includes('달')) {
    const m = expectedDaysStr.match(/(\d+)\s*(개월|달)/);
    if (m) days = parseInt(m[1], 10) * 30;
  } else {
    const m = expectedDaysStr.match(/\d+/);
    if (m) days = parseInt(m[0], 10);
  }

  if (days > 0) {
    const cleanStart = startDateStr.replace(/\./g, '-');
    const parts = cleanStart.split('-');
    if (parts.length === 3) {
      const year = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1;
      const day = parseInt(parts[2], 10);
      const startDate = new Date(year, month, day);
      if (!isNaN(startDate.getTime())) {
        const endDate = new Date(startDate);
        endDate.setDate(endDate.getDate() + (days - 1));

        const y = endDate.getFullYear();
        const m = String(endDate.getMonth() + 1).padStart(2, '0');
        const d = String(endDate.getDate()).padStart(2, '0');
        const formatted = `${y}-${m}-${d}`;

        endDateInput.value = formatted;
        if (endDatePicker) endDatePicker.value = formatted;
        return;
      }
    }
  }

  // 일수 계산이 불가한 경우에도 값 초기화
  endDateInput.value = '';
  if (endDatePicker) endDatePicker.value = '';
}

function onEndDateManualChange() {
  const startDateStr = (document.getElementById('newAppDesiredDate')?.value || '').trim();
  const endDateStr = (document.getElementById('newAppEndDate')?.value || '').trim();
  const daysInput = document.getElementById('newAppExpectedDays');
  if (!startDateStr || !endDateStr || !daysInput) return;

  const cleanStart = startDateStr.replace(/\./g, '-');
  const cleanEnd = endDateStr.replace(/\./g, '-');
  const dStart = new Date(cleanStart);
  const dEnd = new Date(cleanEnd);

  if (!isNaN(dStart.getTime()) && !isNaN(dEnd.getTime()) && dEnd >= dStart) {
    const diffTime = dEnd.getTime() - dStart.getTime();
    const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24)) + 1;
    daysInput.value = `${diffDays}일`;
  }
}

function setExpectedDaysValue(val) {
  const input = document.getElementById('newAppExpectedDays');
  if (input) {
    input.value = val;
    calculateAndSetEndDate();
  }
}

// -------------------------------------------------------------------------
// SAMSUNG MATCHING & HYUNDAI FAX / SMS ENGINES
// -------------------------------------------------------------------------

function checkSamsungEligibleInNewApp() {
  const patName = (document.getElementById('newAppPatientName')?.value || '').trim();
  const phone = (document.getElementById('newAppPhone')?.value || '').trim();
  const rrnFront = (document.getElementById('newAppRrnFront')?.value || '').trim();
  const birthDate = (document.getElementById('newAppBirthDate')?.value || '').trim();

  // 고객 정보가 전혀 입력되지 않았을 경우 첫 번째 고객(김옥경 등)을 임의로 가져오지 않고 안내 처리
  if (!patName && !phone && !rrnFront && !birthDate) {
    showCustomAlert({
      title: '고객 정보 입력 필요',
      message: '조회할 피보험자 고객명 또는 연락처가 입력되지 않았습니다.\n\n사전명단 전체 목록에서 검색하여 고객을 바로 선택하시겠습니까?',
      icon: 'search',
      iconColor: 'sky',
      isConfirm: true
    }).then(confirmed => {
      if (confirmed) {
        openSamsungLeadSearchModal();
      } else {
        const nameEl = document.getElementById('newAppPatientName');
        if (nameEl) nameEl.focus();
      }
    });
    return;
  }

  const cleanPhone = phone.replace(/[^0-9]/g, '');
  const cleanRrnFront = rrnFront.replace(/[^0-9]/g, '');
  const cleanBirth = birthDate.replace(/[^0-9]/g, '');

  const source = (window.gSamsungSheets && gSamsungSheets.eligible && gSamsungSheets.eligible.length > 0)
    ? gSamsungSheets.eligible
    : (window.gSamsungList || []);

  let match = null;

  // 1. 이름과 전화번호 동시 일치
  if (patName && cleanPhone) {
    match = source.find(item => {
      const itemPhone = (item.phone || '').replace(/[^0-9]/g, '');
      return item.patientName === patName && (itemPhone === cleanPhone || (cleanPhone.length >= 8 && itemPhone.endsWith(cleanPhone)));
    });
  }

  // 2. 전화번호로 일치 (7자리 이상 입력 시)
  if (!match && cleanPhone && cleanPhone.length >= 7) {
    match = source.find(item => {
      const itemPhone = (item.phone || '').replace(/[^0-9]/g, '');
      return itemPhone === cleanPhone || (cleanPhone.length >= 8 && itemPhone.endsWith(cleanPhone));
    });
  }

  // 3. 성명 완전 일치 (동명이인이 있을 경우 생년월일 비교)
  if (!match && patName) {
    const candidates = source.filter(item => item.patientName === patName);
    if (candidates.length === 1) {
      match = candidates[0];
    } else if (candidates.length > 1) {
      if (cleanBirth || cleanRrnFront) {
        match = candidates.find(item => {
          const itemBirth = (item.birthDate || '').replace(/[^0-9]/g, '');
          return (cleanBirth && itemBirth === cleanBirth) ||
                 (cleanRrnFront && (itemBirth.slice(2, 8) === cleanRrnFront || itemBirth === cleanRrnFront));
        }) || candidates[0];
      } else {
        match = candidates[0];
      }
    }
  }

  // 4. 성명 부분 일치 (2글자 이상 입력 시)
  if (!match && patName && patName.length >= 2) {
    const partials = source.filter(item => item.patientName && item.patientName.includes(patName));
    if (partials.length === 1) {
      match = partials[0];
    }
  }

  if (match) {
    populateSamsungLeadDataToForm(match);

    showCustomAlert({
      title: '삼성화재 가입고객 확인 완료 (12대 항목 연동)',
      message: `${match.patientName} 고객님은 삼성화재 가입고객으로 정상 확인되었습니다.\n사전명단에 등록된 12대 항목(피보험자ID, 증권번호, 상품코드/명, 계약기간, 담보여부 등) 및 손사 정보가 자동으로 안전하게 채워졌습니다.`,
      icon: 'file-check-2',
      iconColor: 'sky',
      details: [
        `피보험자: ${match.patientName} (${match.gender || '-'} · ${match.birthDate || '-'})`,
        `피보험자ID: ${match.patientId || match.id || '-'}`,
        `증권번호: ${match.policyNumber || '-'}`,
        `보험상품: ${match.productName || '-'} (${match.productCode || '-'})`,
        `계약기간: ${(match.contractStartDate && match.contractEndDate) ? `${match.contractStartDate} ~ ${match.contractEndDate}` : '-'}`,
        `간병담보: 상해(${match.hasInjuryCare || '가입'}), 질병(${match.hasDiseaseCare || '가입'})`,
        `담당손사: ${match.adjusterName || '김정현'} (${match.adjusterPhone || '02-3485-9114'})`
      ]
    });
  } else {
    showCustomAlert({
      title: '삼성화재 사전명단 조회 결과',
      message: `입력하신 정보와 일치하는 삼성화재 가입 고객을 찾지 못했습니다.\n\n고객명(${patName || '-'}) 또는 연락처를 다시 확인해 주세요. 사전명단 목록에서 직접 검색하시겠습니까?`,
      icon: 'alert-triangle',
      iconColor: 'rose',
      isConfirm: true
    }).then(confirmed => {
      if (confirmed) {
        openSamsungLeadSearchModal();
      }
    });
  }
}

function sendHyundaiFaxFromNewApp() {
  const patName = (document.getElementById('newAppPatientName').value || '').trim() || '고객';
  const phone = (document.getElementById('newAppPhone').value || '').trim();

  showCustomAlert({
    title: '현대해상 FAX 발송 완료',
    message: `${patName} 고객님의 신청 정보를 현대해상에 정상적으로 FAX발송 완료하였습니다.\n(수신 팩스: 현대해상 보상지원센터 02-2195-5000)\n\n잠시 후 현대해상에서 리본케어 담당자 핸드폰으로 가입자 안내 문자가 도착합니다.`,
    icon: 'printer',
    iconColor: 'blue',
    details: [
      `발송 서식: [HD_FORM_01] 간병인지원 서비스 신청서`,
      `피보험자: ${patName} (${phone || '연락처 기재됨'})`,
      `수신처: 현대해상화재보험(주) 보상지원팀 (FAX 02-2195-5000)`,
      `전송 상태: 성공 (OK - 200)`
    ]
  });
}

function parseHyundaiSmsFromInput() {
  const textarea = document.getElementById('newAppHdRawSms');
  const smsText = (textarea ? textarea.value : '').trim();

  if (!smsText) {
    alert('수신된 문자 메시지 내용을 입력해주세요.');
    return;
  }

  const parsed = parseHyundaiSmsText(smsText);
  if (!parsed || (!parsed.policyNumber && !parsed.accidentNumber && !parsed.adjusterName)) {
    alert('문자 내용에서 증권번호나 사고번호를 식별하지 못했습니다. 형식을 확인해주세요.');
    return;
  }

  if (parsed.policyNumber && document.getElementById('newAppPolicy')) document.getElementById('newAppPolicy').value = parsed.policyNumber;
  if (parsed.accidentNumber && document.getElementById('newAppAccidentNo')) document.getElementById('newAppAccidentNo').value = parsed.accidentNumber;
  if (parsed.adjusterName && document.getElementById('newAppAdjuster')) document.getElementById('newAppAdjuster').value = parsed.adjusterName;
  if (parsed.adjusterPhone && document.getElementById('newAppAdjusterPhone')) document.getElementById('newAppAdjusterPhone').value = parsed.adjusterPhone;
  if (parsed.productName && document.getElementById('newAppProductName')) document.getElementById('newAppProductName').value = parsed.productName;
  if (parsed.contractPeriod && document.getElementById('newAppContractPeriod')) document.getElementById('newAppContractPeriod').value = parsed.contractPeriod;
  if (parsed.adjusterFirm && document.getElementById('newAppAdjusterFirm')) document.getElementById('newAppAdjusterFirm').value = parsed.adjusterFirm;
  if (parsed.adjusterFax && document.getElementById('newAppAdjusterFax')) document.getElementById('newAppAdjusterFax').value = parsed.adjusterFax;
  if (parsed.adjusterFax && document.getElementById('newAppAdjusterFax')) document.getElementById('newAppAdjusterFax').value = parsed.adjusterFax;

  const memoElem = document.getElementById('newAppMemo');
  if (memoElem && !memoElem.value) {
    memoElem.value = `[현대해상 문자 자동입력] 상품: ${parsed.productName || '-'} / 증권: ${parsed.policyNumber || '-'} / 사고: ${parsed.accidentNumber || '-'}`;
  }

  const detailItems = [];
  if (parsed.policyNumber) detailItems.push(`증권번호: ${parsed.policyNumber}`);
  if (parsed.accidentNumber) detailItems.push(`사고번호: ${parsed.accidentNumber}`);
  if (parsed.adjusterName) detailItems.push(`담당손사: ${parsed.adjusterName}`);
  if (parsed.adjusterPhone) detailItems.push(`손사연락처: ${parsed.adjusterPhone}`);
  if (parsed.adjusterFax) detailItems.push(`손사FAX: ${parsed.adjusterFax}`);

  showCustomAlert({
    title: '현대해상 가입정보 문자 수신 완료',
    message: `${(document.getElementById('newAppPatientName') && document.getElementById('newAppPatientName').value.trim()) || (parsed.patientName || '고객')} 고객님의 현대해상 회신 문자가 실시간 자동 분석되어 증권번호, 사고번호, 담당손사 정보가 성공적으로 입력되었습니다!`,
    icon: 'smartphone',
    iconColor: 'indigo',
    details: detailItems
  });
}

function simulateReceiveHyundaiSms() {
  const patName = (document.getElementById('newAppPatientName').value || '').trim() || '홍길동';
  const samplePolicy = 'L0254' + Math.floor(1000 + Math.random() * 9000);
  const sampleAccident = '2601' + Math.floor(1000 + Math.random() * 9000);
  const sampleAdj = '이보상';
  const samplePhone = '02-2195-5000';
  const sampleFax = '0507-111-2222';

  const rawSms = `[현대해상 보상안내] 환자: ${patName} / 증권번호: ${samplePolicy} / 사고번호: ${sampleAccident} / 담당손사: ${sampleAdj} / 손사연락처: ${samplePhone} / 손사FAX: ${sampleFax} / 비고: 간병인지원 특별약관 정상접수 안내`;

  const textarea = document.getElementById('newAppHdRawSms');
  if (textarea) textarea.value = rawSms;

  parseHyundaiSmsFromInput();
}

// -------------------------------------------------------------------------
// FORM SUBMIT HANDLER (STEP 1 REGISTRATION)
// -------------------------------------------------------------------------

function handleNewAppSubmit(e) {
  if (e && typeof e.preventDefault === 'function') {
    e.preventDefault();
  }

  try {
    const missing = (typeof updateNewAppValidationHighlight === 'function') ? updateNewAppValidationHighlight(true) : [];
    if (missing && missing.length > 0) {
      if (typeof showCustomAlert === 'function') {
        showCustomAlert({
          title: '필수 입력 정보 누락',
          message: `신규 접수를 완료하려면 빨간색 테두리로 강조된 필수 항목을 모두 입력해주세요.\n\n[미입력 필수 항목]\n• ${missing.join('\n• ')}`,
          icon: 'alert-circle',
          iconColor: 'rose'
        });
      } else {
        alert(`필수 입력 정보가 누락되었습니다.\n빨간색 테두리로 표시된 항목(${missing.join(', ')})을 모두 입력해주세요.`);
      }
      return;
    }

    const name = document.getElementById('newAppPatientName')?.value?.trim();
    const phone = document.getElementById('newAppPhone')?.value?.trim();
    const insurance = document.getElementById('newAppInsurance')?.value || '현대해상(SCOR)';
    const gender = document.getElementById('newAppGender')?.value || '남';
    const birthDate = document.getElementById('newAppBirthDate')?.value?.trim() || '';

    if (!name || !phone) {
      alert('피보험자 성명과 연락처를 입력해주세요.');
      return;
    }

    const newId = generateNextAppId();

    // Address extracted from care location (자택 vs 입원)
    const careTypeVal = document.getElementById('newAppCareType')?.value || '입원';
    const isHome = (careTypeVal === '자택' || careTypeVal === '재택');
    let sido = '';
    let sigungu = '';
    let roadAddr = '';
    let detailAddr = '';

    if (isHome) {
      roadAddr = (document.getElementById('newAppCareRoadAddress')?.value || '').trim();
      detailAddr = (document.getElementById('newAppCareDetailAddress')?.value || '').trim();
      if (roadAddr) {
        const parts = roadAddr.split(' ');
        sido = parts[0] || '서울';
        sigungu = parts[1] || '';
      }
    } else {
      const hospName = (document.getElementById('newAppHospitalName')?.value || '').trim();
      const hospRoad = (document.getElementById('newAppHospitalRoadAddress')?.value || '').trim();
      const hospDetail = (document.getElementById('newAppHospitalDetailAddress')?.value || '').trim();
      roadAddr = hospRoad;
      detailAddr = (hospName + ' ' + hospDetail).trim();
      if (hospRoad) {
        const parts = hospRoad.split(' ');
        sido = parts[0] || '서울';
        sigungu = parts[1] || '';
      }
    }
    const fullCombinedAddress = roadAddr ? (roadAddr + (detailAddr ? ' ' + detailAddr : '')) : (detailAddr || '상세주소 미입력');

    // Applicant info & RRN
    const rrnFront = document.getElementById('newAppRrnFront')?.value?.trim() || '';
    const rrnBack = document.getElementById('newAppRrnBack')?.value?.trim() || '';
    const isApplicantSame = document.getElementById('chkApplicantSameAsPatient')?.checked || false;

    const applicantName = document.getElementById('newAppApplicantName')?.value?.trim() || name;
    const applicantBirth = document.getElementById('newAppApplicantBirth')?.value?.trim() || birthDate;
    const applicantPhone = document.getElementById('newAppApplicantPhone')?.value?.trim() || phone;
    let applicantRelation = document.getElementById('newAppApplicantRelation')?.value || '본인';
    if (applicantRelation === '기타') {
      applicantRelation = document.getElementById('newAppApplicantRelationOther')?.value?.trim() || '기타';
    }

    // Care details
    const applyDate = document.getElementById('newAppApplyDate')?.value || new Date().toISOString().split('T')[0];
    const accidentDate = document.getElementById('newAppAccidentDate')?.value?.trim() || applyDate;
    const careEndDate = document.getElementById('newAppEndDate')?.value?.trim() || '';
    const accidentTypeRadio = document.querySelector('input[name="newAppAccidentTypeRadio"]:checked');
    const accidentType = accidentTypeRadio ? accidentTypeRadio.value : '상해';
    const diagnosis = document.getElementById('newAppDiagnosis')?.value?.trim() || '';
    const accidentDetail = document.getElementById('newAppAccidentDetail')?.value?.trim() || '';
    const docAttachedRadio = document.querySelector('input[name="newAppDocAttached"]:checked');
    const docAttached = docAttachedRadio ? docAttachedRadio.value : '아니오';
    const mobilityRadio = document.querySelector('input[name="newAppMobility"]:checked');
    const mobility = mobilityRadio ? mobilityRadio.value : '미선택';
    const careType = isHome ? '자택' : '입원';
    const hospitalName = !isHome 
      ? ((document.getElementById('newAppHospitalName')?.value || '') + ' ' + (document.getElementById('newAppHospitalDetailAddress')?.value || '')).trim()
      : '자택 간병';
    const desiredDate = document.getElementById('newAppDesiredDate')?.value || applyDate;
    const expectedDays = document.getElementById('newAppExpectedDays')?.value?.trim() || '30일';

    // Additional fields (safely read)
    const productName = document.getElementById('newAppProductName')?.value?.trim() || '';
    const contractPeriod = document.getElementById('newAppContractPeriod')?.value?.trim() || '';
    const policyNumber = document.getElementById('newAppPolicy')?.value?.trim() || '';
    const accidentNumber = document.getElementById('newAppAccidentNo')?.value?.trim() || '';
    const adjusterName = document.getElementById('newAppAdjuster')?.value?.trim() || '';
    const adjusterFirm = document.getElementById('newAppAdjusterFirm')?.value?.trim() || '';
    const adjusterPhone = document.getElementById('newAppAdjusterPhone')?.value?.trim() || '';
    const adjusterMobile = document.getElementById('newAppAdjusterMobile')?.value?.trim() || '';
    const adjusterFax = document.getElementById('newAppAdjusterFax')?.value?.trim() || '';
    const rawMemo = document.getElementById('newAppMemo')?.value?.trim() || '';

    let formattedMemo = rawMemo;
    if (diagnosis) {
      formattedMemo = `[진단명: ${diagnosis}] ` + formattedMemo;
    }
    if (hospitalName) {
      formattedMemo += ` (장소: ${hospitalName})`;
    }

    const isHyundai = insurance.includes('현대해상');
    const defaultHdStage = isHyundai ? '문자수신대기' : '사전명단매칭완료';

    const targetFaxRecipient = document.getElementById('newAppFaxRecipient')?.value?.trim() || '';
    const targetFaxNumber = document.getElementById('newAppFaxNumber')?.value?.trim() || '';

    const newApp = {
      id: newId,
      patientName: name,
      gender: gender,
      birthDate: birthDate || '-',
      phone: phone,
      sido: sido || '서울',
      sigungu: sigungu || '',
      addressDetail: fullCombinedAddress,
      insuranceCompany: insurance,
      productName: productName || (isHyundai ? '무배당현대해상내삶엔(3N)맞춤간편건강보험' : '삼성화재 다이렉트 간병보험'),
      contractPeriod: contractPeriod || (isHyundai ? '2025-07-17 ~ 2045-07-17' : '2024-03-01 ~ 2044-03-01'),
      policyNumber: policyNumber || '-',
      contractDate: '-',
      accidentNumber: accidentNumber || '-',
      adjusterName: adjusterName || '-',
      adjusterFirm: adjusterFirm || (isHyundai ? '하이라이프.부산손사4팀' : '삼성애니카손해사정'),
      adjusterPhone: adjusterPhone || '-',
      adjusterMobile: adjusterMobile || '-',
      adjusterFax: targetFaxNumber,
      accidentDate: accidentDate,
      accidentType: accidentType,
      applyDate: applyDate,
      desiredDate: desiredDate,
      careType: careType,
      hospitalName: !isHome ? (document.getElementById('newAppHospitalName')?.value || '').trim() : '자택 간병',
      hospitalRoom: !isHome ? (document.getElementById('newAppHospitalDetailAddress')?.value || '').trim() : '',
      hospitalRoadAddress: !isHome ? (document.getElementById('newAppHospitalRoadAddress')?.value || '').trim() : '',
      expectedDays: expectedDays,
      careEndDate: careEndDate,
      status: '접수',
      applicantName: applicantName,
      applicantBirth: applicantBirth,
      applicantPhone: applicantPhone,
      applicantRelation: applicantRelation,
      isApplicantSame: isApplicantSame,
      rrnFront: rrnFront,
      rrnBack: rrnBack,
      patientRrn: (rrnFront && rrnBack) ? `${rrnFront}-${rrnBack}` : (rrnFront ? `${rrnFront}-*******` : ''),
      docAttached: docAttached,
      mobility: mobility,
      accidentDetail: accidentDetail,
      hdWorkflowStage: defaultHdStage,
      assignedCaregiverCount: 0,
      totalPayout: 0,
      claimCount: 0,
      unconfirmedClaimCount: 0,
      depositConfirmedAmount: 0,
      estimatedUnpaid: 0,
      memo: formattedMemo.trim(),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    if (insurance.includes('삼성')) {
      const domPatientId = document.getElementById('newAppSamsungPatientId')?.value?.trim();
      const domPolicyNumber = document.getElementById('newAppSamsungPolicyNumber')?.value?.trim();
      const domProductCode = document.getElementById('newAppSamsungProductCode')?.value?.trim();
      const domProductName = document.getElementById('newAppSamsungProductName')?.value?.trim();
      const domContractStart = document.getElementById('newAppSamsungContractStartDate')?.value?.trim();
      const domContractEnd = document.getElementById('newAppSamsungContractEndDate')?.value?.trim();
      const domHasInjury = document.getElementById('newAppSamsungHasInjuryCare')?.value?.trim();
      const domHasDisease = document.getElementById('newAppSamsungHasDiseaseCare')?.value?.trim();
      const domAdjuster = document.getElementById('newAppSamsungAdjuster')?.value?.trim();
      const domAdjusterPhone = document.getElementById('newAppSamsungAdjusterPhone')?.value?.trim();
      const domAdjusterFax = document.getElementById('newAppSamsungAdjusterFax')?.value?.trim();
      const domAccidentNo = document.getElementById('newAppSamsungAccidentNumber')?.value?.trim();

      newApp.patientId = domPatientId || gPendingSamsungLeadData?.patientId || ('SF-P' + (100 + gApps.length));
      newApp.productCode = domProductCode || gPendingSamsungLeadData?.productCode || '2PB320070';
      newApp.productName = domProductName || gPendingSamsungLeadData?.productName || newApp.productName || '무배당 삼성화재 간편보험 다이렉트(2603.5)(납입면제/해약환급금 미지급형Ⅱ)';
      newApp.contractStartDate = domContractStart || gPendingSamsungLeadData?.contractStartDate || '2026-09-09';
      newApp.contractEndDate = domContractEnd || gPendingSamsungLeadData?.contractEndDate || '2046-09-09';
      if (newApp.contractStartDate && newApp.contractEndDate) {
        newApp.contractPeriod = `${newApp.contractStartDate} ~ ${newApp.contractEndDate}`;
      }
      newApp.hasInjuryCare = domHasInjury || gPendingSamsungLeadData?.hasInjuryCare || '가입';
      newApp.hasDiseaseCare = domHasDisease || gPendingSamsungLeadData?.hasDiseaseCare || '가입';

      if (domPolicyNumber) newApp.policyNumber = domPolicyNumber;
      if (domAdjuster) newApp.adjusterName = domAdjuster;
      if (domAdjusterPhone) newApp.adjusterPhone = domAdjusterPhone;
      if (domAdjusterFax) newApp.adjusterFax = domAdjusterFax;
      if (domAccidentNo) newApp.accidentNumber = domAccidentNo;

      gPendingSamsungLeadData = null;
    }

    if (isHyundai && targetFaxNumber) {
      // 1차 고객등록 및 신청 팩스는 수신 팩스번호가 지정된 경우에만 미리보기 및 발송 진행
      newApp.initialFaxSent = true;
      newApp.initialFaxDate = new Date().toISOString().split('T')[0].replace(/-/g, '.');
      newApp.pendingFaxRecipient = targetFaxRecipient || '현대해상 보상지원센터';
      newApp.pendingFaxNumber = targetFaxNumber;

      // 현대해상인 경우 바로 저장/발송하지 않고, 서식 미리보기 창을 띄워 확인 후 최종 발송을 진행
      window.gPendingNewApp = newApp;
      previewFormForCustomer('HD_FORM_01', newApp, true, newApp.pendingFaxRecipient, targetFaxNumber);
      return;
    }

    // 팩스번호 미지정 또는 타 보험사인 경우 즉시 접수 등록
    newApp.pendingFaxRecipient = targetFaxRecipient;
    newApp.pendingFaxNumber = targetFaxNumber;
    finalizeNewAppRegistration(newApp);
  } catch (err) {
    console.error('신규 접수 저장 중 오류 발생:', err);
    alert('신규 신청 저장 중 오류가 발생했습니다: ' + err.message);
  }
}

async function finalizeNewAppRegistration(newApp) {
  try {
    const isHyundai = (newApp.insuranceCompany || '').includes('현대해상');
    const newId = newApp.id;
    const targetFaxRecipient = newApp.pendingFaxRecipient || '';
    const targetFaxNumber = newApp.pendingFaxNumber || '';

    // 팩스번호가 실제로 입력된 경우에만 팩스 발송 및 발송 대장 기록 수행
    if (targetFaxNumber) {
      if (isHyundai) {
        if (typeof window.gInitialFaxRecords === 'undefined') {
          window.gInitialFaxRecords = {};
        }
        window.gInitialFaxRecords[newId] = {
          formType: 'HD_FORM_01',
          formTitle: '현대해상 간병인지원 신청/고객등록 요청서',
          sentDate: newApp.initialFaxDate || new Date().toISOString().split('T')[0].replace(/-/g, '.'),
          status: '전송완료',
          faxNumber: targetFaxNumber + (targetFaxRecipient ? ' (' + targetFaxRecipient + ')' : ''),
          recipient: targetFaxRecipient || '현대해상 보상지원센터',
          pages: 1,
          deliveryStatus: '성공 (OK - 200)'
        };
        // 청구 팩스(Claim Fax) 이력과 섞이지 않도록 gFaxRecords에서는 확실히 제외/삭제
        if (typeof gFaxRecords !== 'undefined' && gFaxRecords[newId]) {
          delete gFaxRecords[newId];
        }
      }
      // 실제 팩스 게이트웨이(/api/fax/send - 바로빌/알리고) 실시간 전송 호출
      const cfg = getBarobillConfig();
      let savedBaroPwd = cfg.baroPwd;
      if (!savedBaroPwd) {
        savedBaroPwd = await ensureBarobillPassword();
      }

      if (!savedBaroPwd && cfg.mode === 'barobill') {
        showCustomAlert({
          title: '바로빌 팩스 비밀번호 확인 필요',
          message: '현대해상 1차 고객등록 팩스 발송을 위한 바로빌 계정 비밀번호가 아직 설정되지 않았습니다.\n\n[팩스관리]의 [팩스 설정] 창에서 비밀번호를 1회만 등록하시면 모든 팩스 발송에 자동 적용됩니다.',
          icon: 'shield-alert',
          iconColor: 'amber',
          confirmText: '팩스 설정 열기',
          onConfirm: () => {
            openFaxSettingsModal();
            setTimeout(() => {
              const pwdEl = document.getElementById('faxBarobillPwd');
              if (pwdEl) pwdEl.focus();
            }, 300);
          }
        });
        return;
      }

      let dispatchFaxNumber = targetFaxNumber;
      let redirectNote = '';

      // 대상 수신처가 사내 테스트 회선(복합기, 모바일팩스 등)이거나 사내 번호인 경우 리다이렉트 제외하고 지정 수신처로 직송
      const cleanTargetNum = (targetFaxNumber || '').replace(/[^0-9]/g, '');
      const isTargetInternalOrTest = 
        (targetFaxRecipient && (
          targetFaxRecipient.includes('복합기') || 
          targetFaxRecipient.includes('테스트') || 
          targetFaxRecipient.includes('리본케어') || 
          targetFaxRecipient.includes('모바일팩스')
        )) || 
        cleanTargetNum === '0264993917' ||
        cleanTargetNum === (cfg.testRedirectNumber || '').replace(/[^0-9]/g, '');

      const applyRedirect = cfg.isTestRedirect && cfg.testRedirectNumber && !isTargetInternalOrTest;
      if (applyRedirect) {
        dispatchFaxNumber = cfg.testRedirectNumber;
        redirectNote = `\n[안전 테스트 리다이렉트: 원본(${targetFaxRecipient} ${targetFaxNumber}) 대신 테스트번호(${cfg.testRedirectNumber})로 송출됨]`;
      }

      const previewHtml = getCleanFaxTransmissionHtml('HD_FORM_01');

      const faxPayload = {
        appId: newApp.id,
        patientName: newApp.patientName,
        insuranceCompany: newApp.insuranceCompany,
        category: '1차접수',
        formCode: 'HD_FORM_01',
        formName: '현대해상 1차 고객등록 및 신청 접수서',
        recipient: targetFaxRecipient + (applyRedirect ? ' (테스트 리다이렉트)' : ''),
        faxNumber: dispatchFaxNumber,
        senderNumber: cfg.sender,
        memo: (newApp.memo || '현대해상 1차 고객등록 및 신청 접수 건 송부') + redirectNote,
        pages: 1,
        formHtml: previewHtml,
        operator: '접수담당자',
        provider: cfg.mode,
        baroCertKey: cfg.certKey,
        baroCorpNum: cfg.corpNum,
        baroId: cfg.baroId,
        baroPwd: savedBaroPwd,
        baroServer: cfg.baroServer,
        aligoUserId: cfg.aligoUser,
        aligoKey: cfg.aligoKey
      };

      let resultLog = null;
      let sendErrorMessage = '';
      try {
        const res = await fetch('/api/fax/send', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(faxPayload)
        });
        const data = await res.json();
        if (data && data.success && data.log) {
          resultLog = data.log;
        } else if (data && !data.success) {
          sendErrorMessage = data.error || '발송 실패';
        }
      } catch (apiErr) {
        console.warn('[FAX API Call Error in newApp]', apiErr);
        sendErrorMessage = apiErr.message || '네트워크 연결 오류';
      }

      if (!resultLog) {
        const now = new Date();
        const dateStr = now.getFullYear() + '.' + String(now.getMonth() + 1).padStart(2, '0') + '.' + String(now.getDate()).padStart(2, '0') + ' ' + String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');
        const isFailed = Boolean(sendErrorMessage);
        resultLog = {
          id: 'FLOG-' + Date.now().toString().slice(-6),
          sentDate: dateStr,
          appId: newApp.id,
          patientName: newApp.patientName,
          insuranceCompany: '현대해상',
          category: '1차접수',
          formCode: 'HD_FORM_01',
          formName: '현대해상 1차 고객등록 및 신청 접수서',
          recipient: targetFaxRecipient,
          faxNumber: dispatchFaxNumber,
          pages: 1,
          status: isFailed ? '실패' : '성공',
          operator: '접수담당자',
          resultMsg: isFailed ? `발송 실패 (${sendErrorMessage})` : (savedMode === 'barobill' ? '바로빌 접수 완료' : '정상 송신 완료 (200 OK)'),
          provider: savedMode === 'barobill' ? `Barobill (${savedBaroServer === 'prod' ? '운영' : '테스트'})` : (savedMode === 'aligo' ? 'Aligo Fax API' : 'Smart Sandbox (모의 회선)')
        };
      }

      if (!Array.isArray(gFaxLogs)) gFaxLogs = [];
      gFaxLogs.unshift(resultLog);
      if (typeof saveFaxLogs === 'function') saveFaxLogs();
      if (typeof updateFaxKpis === 'function') updateFaxKpis();
      if (typeof renderFaxLogsTable === 'function') renderFaxLogsTable();
      try {
        if (typeof syncToConvex === 'function') {
          await syncToConvex('sync:saveFaxRecord', { record: resultLog });
        }
      } catch (e) {}
    }

    // Add to applications
    gApps.unshift(newApp);

    // 손해사정인 정보 디렉토리 자동반영 & 동기화
    if (newApp.adjusterName) {
      autoSyncAdjusterToDirectory({
        name: newApp.adjusterName,
        insuranceCompany: newApp.insuranceCompany,
        phone: newApp.adjusterPhone,
        fax: newApp.adjusterFax,
        firm: newApp.adjusterFirm
      });
    }

    // Convex Cloud 운영 DB 실시간 동기화
    if (typeof syncToConvex === 'function') {
      syncToConvex('sync:saveApplication', { app: newApp });
    }

    // Increment seq
    incrementAppIdSeq();

    closeModal('newAppModal');
    renderUnifiedCareHub();
    renderApplications();
    renderDashboard();

    if (isHyundai && targetFaxNumber) {
      showCustomAlert({
        title: '현대해상 1차 접수 & 팩스 발송 완료',
        message: `[${newId} - ${newApp.patientName} 님]의 현대해상 1차 접수가 성공적으로 완료되어 ${targetFaxRecipient}(FAX ${targetFaxNumber})으로 고객등록 팩스가 발송되었습니다.\n\n현재 고객 상태는 [문자수신대기]로 등록되었습니다.\n현대해상으로부터 피보험자 가입정보 회신 문자가 도착하면, 고객 카드나 간병신청대장의 [📱 현대 문자 등록] 버튼을 눌러 문자를 붙여넣으시면 증권/사고/손사 정보가 1초 만에 자동 완성됩니다.`,
        icon: 'printer',
        iconColor: 'blue',
        details: [
          `접수번호: ${newId}`,
          `피보험자: ${newApp.patientName} (${newApp.gender} · ${newApp.phone})`,
          `원수사: ${newApp.insuranceCompany}`,
          `발송 팩스: [HD_FORM_01] 간병인지원 신청/고객등록 요청서 (수신: ${targetFaxNumber})`,
          `수신처: ${targetFaxRecipient}`,
          `진행 단계: [문자수신대기] (회신 문자 수신 시 [📱 현대 문자 등록]으로 1초 완료)`
        ]
      });
    } else {
      showCustomAlert({
        title: '신규 간병신청 접수 완료 (STEP 1)',
        message: `[${newId} - ${newApp.patientName} 님]의 간병인지원 서비스 신청 접수가 성공적으로 등록되었습니다.\n통합 간병 운영 허브와 간병신청대장에 즉시 동기화되었습니다.`,
        icon: 'check-circle-2',
        iconColor: 'emerald',
        details: [
          `접수번호: ${newId}`,
          `피보험자: ${newApp.patientName} (${newApp.gender} · ${newApp.phone})`,
          `원수사: ${newApp.insuranceCompany}`,
          `간병시작 희망일: ${newApp.desiredDate} (${newApp.careType})`
        ]
      });
    }

    if ((newApp.insuranceCompany || '').includes('삼성')) {
      syncSamsungSpreadsheetData(true);
    }
  } catch (err) {
    console.error('신규 접수 저장 중 오류 발생:', err);
    alert('신규 신청 저장 중 오류가 발생했습니다: ' + err.message);
  }
}

function openNewAssignModal(targetApplyId = null, isReplacement = false) {
  const select = document.getElementById('newAssignApplySelect');
  if (select) {
    select.innerHTML = gApps.map(a => `
      <option value="${a.id}" ${targetApplyId && a.id === targetApplyId ? 'selected' : ''}>${a.id} - ${a.patientName} (${a.insuranceCompany})</option>
    `).join('');
    if (targetApplyId) {
      select.value = targetApplyId;
      select.disabled = true;
    } else {
      select.disabled = false;
    }
  }

  // Set replacement mode state
  const isRepEl = document.getElementById('newAssignIsReplacement');
  const prevAssignIdEl = document.getElementById('newAssignPrevAssignId');
  const titleEl = document.getElementById('newAssignModalTitle');
  const subEl = document.getElementById('newAssignModalSub');
  const submitBtnEl = document.getElementById('newAssignSubmitBtn');

  // Find existing assignments for this application if in replacement mode
  let prevAssign = null;
  if (targetApplyId) {
    const existingAssigns = (gAssigns || []).filter(a => a.applyId === targetApplyId);
    if (existingAssigns.length > 0) {
      const sorted = existingAssigns.slice().sort((a, b) => (a.startDate || '').localeCompare(b.startDate || ''));
      prevAssign = sorted[sorted.length - 1];
    }
  }

  if (isReplacement && prevAssign) {
    if (isRepEl) isRepEl.value = 'true';
    if (prevAssignIdEl) prevAssignIdEl.value = prevAssign.id;
    if (titleEl) titleEl.innerText = `간병인 교체 등록 (기존: ${prevAssign.caregiverName} 님)`;
    if (subEl) subEl.innerText = `기존 간병인 [${prevAssign.caregiverName}] 님의 근무를 종료하고 후임 간병인을 새로 투입합니다. 기존 정산 내역은 안전하게 보존됩니다.`;
    if (submitBtnEl) submitBtnEl.innerText = '교체 배정 완료 🔄';
  } else {
    if (isRepEl) isRepEl.value = 'false';
    if (prevAssignIdEl) prevAssignIdEl.value = '';
    if (titleEl) titleEl.innerText = '간병인 배정 등록';
    if (subEl) subEl.innerText = '신청 건에 매칭할 간병인 및 일급을 등록합니다.';
    if (submitBtnEl) submitBtnEl.innerText = '배정 완료';
  }

  // Clear name and input fields for new input
  const nameEl = document.getElementById('newAssignCaregiverName');
  if (nameEl) nameEl.value = '';
  const phoneEl = document.getElementById('newAssignCaregiverPhone');
  if (phoneEl) phoneEl.value = '';
  const acctEl = document.getElementById('newAssignAccount');
  if (acctEl) acctEl.value = '';

  // Pre-fill dates
  const todayStr = new Date().toISOString().split('T')[0];
  let defaultStartDate = todayStr.replace(/-/g, '.') + ' 09:00';
  let defaultEndDate = todayStr.replace(/-/g, '.') + ' 09:00';

  if (isReplacement && prevAssign && prevAssign.endDate) {
    // If previous caregiver has an endDate, 후임 간병인 starts around now or prevAssign endDate
    defaultStartDate = todayStr.replace(/-/g, '.') + ' 09:00';
    defaultEndDate = prevAssign.endDate; // inherit target schedule end date
  }

  populateCombinedDateTime('newAssignStartDate', defaultStartDate);
  populateCombinedDateTime('newAssignEndDate', defaultEndDate);

  openModal('newAssignModal');
  initIcons();
}

function handleNewAssignSubmit(e) {
  e.preventDefault();
  const select = document.getElementById('newAssignApplySelect');
  const applyId = select ? select.value : '';
  const app = gApps.find(a => a.id === applyId);
  const name = document.getElementById('newAssignCaregiverName').value.trim();
  const wageRaw = document.getElementById('newAssignDailyWage').value.replace(/[^0-9]/g, '');

  syncCombinedDateTime('newAssignStartDate');
  syncCombinedDateTime('newAssignEndDate');

  const isRepEl = document.getElementById('newAssignIsReplacement');
  const isReplacement = isRepEl && isRepEl.value === 'true';
  const prevAssignId = document.getElementById('newAssignPrevAssignId')?.value || '';

  let maxNum = 0;
  (gAssigns || []).forEach(as => {
    if (as && as.id) {
      const n = parseInt(as.id.replace(/[^0-9]/g, ''), 10);
      if (!isNaN(n) && n > maxNum) maxNum = n;
    }
  });
  const newAssignId = 'A0' + String(maxNum + 1).padStart(3, '0');

  const newStartDate = document.getElementById('newAssignStartDate').value || '';
  const newEndDate = document.getElementById('newAssignEndDate').value || '';

  // If replacement mode, safely truncate previous caregiver's endDate to new caregiver's startDate
  let prevAssign = null;
  if (isReplacement && prevAssignId) {
    prevAssign = (gAssigns || []).find(a => a.id === prevAssignId);
    if (prevAssign) {
      prevAssign.endDate = newStartDate;
      prevAssign.updatedAt = new Date().toISOString();
      if (typeof syncToConvex === 'function') {
        syncToConvex('sync:saveAssignment', { assign: prevAssign });
      }
    }
  }

  const newAssign = {
    id: newAssignId,
    applyId: applyId,
    patientName: app ? app.patientName : '고객',
    caregiverName: name,
    birthDate: '',
    phone: document.getElementById('newAssignCaregiverPhone').value || '',
    centerName: document.getElementById('newAssignCenterName').value || '영등포센터',
    centerPhone: '',
    settlementType: document.getElementById('newAssignSettlementType').value || '개인',
    dailyWage: Number(wageRaw) || 140000,
    assignedDate: new Date().toISOString().split('T')[0],
    startDate: newStartDate,
    endDate: newEndDate,
    accountInfo: document.getElementById('newAssignAccount').value || ''
  };

  gAssigns.unshift(newAssign);
  gActiveCaregiverTabAssignId = newAssign.id; // Switch active caregiver tab to newly assigned caregiver

  if (app) {
    app.assignedCaregiverCount = (app.assignedCaregiverCount || 0) + 1;
    app.status = '진행중';
    if (!isReplacement) {
      app.careStartDate = newAssign.startDate;
    }
  }

  // 간병인 및 협력센터 디렉토리 자동반영 & 동기화
  if (name) {
    autoSyncCaregiverToDirectory({
      name: name,
      phone: newAssign.phone,
      centerName: newAssign.centerName,
      account: newAssign.accountInfo,
      dailyWage: newAssign.dailyWage,
      settlementType: newAssign.settlementType,
      area: (app && app.sido) ? `${app.sido} ${app.sigungu || ''}` : '전국'
    });
  }
  if (newAssign.centerName) {
    autoSyncCenterToDirectory({
      name: newAssign.centerName,
      settlementType: newAssign.settlementType
    });
  }

  if (select) select.disabled = false;

  closeModal('newAssignModal');
  if (applyId) {
    moveAppToFront(applyId);
  }
  renderUnifiedCareHub();
  renderAssignments();
  renderApplications();
  renderDashboard();

  // 열려있는 고객상세 팝업이 있다면 즉시 최신 간병인 배정 데이터로 재렌더링
  const hubModal = document.getElementById('hubCustomerDetailModal');
  if (hubModal && !hubModal.classList.contains('hidden') && (gActiveHubModalAppId || applyId)) {
    openHubCustomerDetailModal(gActiveHubModalAppId || applyId);
  }

  // Convex Cloud 운영 DB 실시간 동기화
  if (typeof syncToConvex === 'function') {
    syncToConvex('sync:saveAssignment', { assign: newAssign });
    if (app) syncToConvex('sync:saveApplication', { app: app });
  }

  if (isReplacement && prevAssign) {
    showCustomAlert({
      title: '간병인 교체 배정 완료 🔄',
      message: `[${app ? app.patientName : '고객'}] 님의 간병인이 성공적으로 교체되었습니다.\n- 기존 간병인: [${prevAssign.caregiverName}] (종료: ${prevAssign.endDate})\n- 후임 간병인: [${name}] (투입: ${newAssign.startDate})\n기존 간병인의 근무기간 정산 데이터는 카드 탭에서 영구 보존됩니다.`,
      icon: 'refresh-cw',
      iconColor: 'amber'
    });
  } else {
    showCustomAlert({
      title: '간병인 배정 완료 (STEP 2)',
      message: `[${app ? app.patientName : '고객'}] 님에게 간병인 [${name}] 님이 성공적으로 배정되었습니다.\n배정번호: ${newAssign.id} (일급: ${formatCurrency(newAssign.dailyWage)}원)`,
      icon: 'user-check',
      iconColor: 'emerald'
    });
  }
}

